window.HS_LOAD(9,{"intro":[[["کن اسباب کی وجہ سے صحابہ کرامؓ کی غیبی مدد ہوا کرتی تھی اور وہ کس طرح ان اسباب کے ساتھ چمٹے رہتے تھے اور ان حضرات نے کس طرح اپنی نگاہ مادی اسباب اور فانی سامان سے ہٹا رکھی تھی",""]]],"topics":{"284":{"lead":[],"stories":[{"b":[["n",[["حضرت عبدالرحمٰن بن عوفؓ","b"],[" فرماتے ہیں اسلام ناگواریوں اور سختیوں کو لے کر اترا ہے یعنی ناگواریاں اور سختیاں برداشت کرنے سے اسلام کو ترقی ملتی ہے۔ ہم نے سب سے زیادہ بھلائی ناگواری میں پائی۔ چنانچہ ہم حضورؐ کے ساتھ مکہ سے (ہجرت کر کے بڑی ناگواری کے ساتھ) نکلے لیکن ",""],["ٱللَّٰه","a"],[" نے اسی ہجرت کی وجہ سے ہمیں بلندی اور کامیابی عطا فرمائی۔ اسی طرح ہم حضورؐ کے ساتھ غزوۂ بدر میں گئے تھے۔ اس وقت ہمارا حال وہ تھا جسے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ان آیات میں بیان فرمایا ہے",""]]],["q",[["﴿وَإِنَّ فَرِيْقًا مِّنَ الْمُؤْمِنِيْنَ لَكٰرِهُوْنَ ○ يُجَادِلُوْنَكَ فِي الْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُوْنَ إِلَى الْمَوْتِ وَهُمْ يَنْظُرُوْنَ ○ وَإِذْ يَعِدُكُمُ اللّٰهُ إِحْدَى الطَّائِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّوْنَ أَنَّ غَيْرَ ذَاتِ الشَّوْكَةِ تَكُوْنُ لَكُمْ﴾","a"]]],["p",[["ترجمہ: \"اور مسلمانوں کی ایک جماعت اس کو گراں سمجھتی تھی (اور) وہ اس مصلحت (کے کام) میں، بعد اس کے کہ اس کا ظہور ہو گیا تھا (اپنے بچاؤ کے لیے) آپ سے (بطورِ مشورہ) اس طرح جھگڑ رہے تھے کہ گویا کوئی ان کو موت کی طرف ہانکے لیے جاتا ہے اور وہ دیکھ رہے ہیں۔ اور تم لوگ اس وقت کو یاد کرو جبکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ تم سے ان دو جماعتوں سے ایک کا وعدہ کرتے تھے کہ وہ تمہارے ہاتھ آ جائے گی اور تم اس تمنا میں تھے کہ غیر مسلح جماعت (یعنی قافلہ) تمہارے ہاتھ آ جاوے۔\" (سورۂ انفال، آیت 5 تا 7)۔ اور مسلح جماعت قریش کی تھی۔ چنانچہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس سفر میں بھی ہمارے لیے بلندی اور کامیابی رکھ دی (حالانکہ یہ غزوہ ہماری مرضی کے بالکل خلاف ہوا تھا)۔ خلاصہ یہ ہے کہ ہم نے بھلائی کی بھلائی ناگواری میں پائی۔",""],[" (1)","s"]]]],"f":[["(1)","Bazzaar; Haythami (Vol.7 Pg.27) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت محمد بن اسحاق بن یسارؒ","b"],[" نے حضرت خالد بن ولیدؓ کا قصہ ذکر کیا ہے کہ جب حضرت خالدؓ یمامہ سے فارغ ہوئے تو حضرت ابوبکر صدیقؓ نے انہیں یمامہ یہ خط لکھا: حضورؐ کے خلیفہ اور ",""],["ٱللَّٰه","a"],[" کے بندے ابوبکرؓ کی طرف سے حضرت خالد بن ولید کے نام اور ان مہاجرین انصار اور اخلاص کے ساتھ ان کا اتباع کرنے والوں کے نام جو حضرت خالد کے ساتھ ہیں، سلام علیکم۔ میں آپ لوگوں کے سامنے اس ",""],["ٱللَّٰه","a"],[" کی تعریف کرتا ہوں جس کے سوا کوئی معبود نہیں۔ اما بعد! تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے اپنا وعدہ پورا کیا اور اپنے بندے کی مدد کی اور اپنے دوست کو عزت دی اور اپنے دشمن کو ذلیل کیا اور تمام گروہوں پر اکیلا ہی غالب آ گیا۔ وہ ",""],["ٱللَّٰه","a"],[" جس کے سوا کوئی معبود نہیں اس نے یہ فرمایا ہے",""]]],["q",[["﴿وَعَدَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا مِنْكُمْ وَعَمِلُوا الصّٰلِحٰتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِيْنَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِيْنَهُمُ الَّذِي ارْتَضٰى لَهُمْ﴾","a"]]],["p",[["ترجمہ: \"(اے مجموعۂ امت) تم میں جو لوگ ایمان لاویں اور نیک عمل کریں ان سے ",""],["ٱللَّٰه","a"],[" تعالیٰ وعدہ فرماتا ہے کہ ان کو (اس اتباع کی برکت سے) زمین میں حکومت عطا فرمائے گا جیسا کہ ان سے پہلے (اہلِ ہدایت) لوگوں کو حکومت دی تھی اور جس دین کو (",""],["ٱللَّٰه","a"],[" تعالیٰ نے) ان کے لیے پسند فرمایا ہے (یعنی اسلام) اس کو ان کے (نفعِ آخرت کے) لیے قوت دے گا۔\" (سورۂ نور، آیت 55)۔ حضرت ابوبکرؓ نے یہ پوری آیت لکھی۔ اس کے بعد لکھا یہ ",""],["ٱللَّٰه","a"],[" کا وعدہ ہے جس کے خلاف کبھی نہیں ہو سکتا اور ",""],["ٱللَّٰه","a"],[" کا فرمان ایسا ہے جس میں کوئی شک نہیں ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مسلمانوں پر جہاد فرض کیا ہے اور قرآن میں فرمایا ہے",""]]],["q",[["﴿كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ﴾","a"]]],["p",[["ترجمہ: \"جہاد کرنا تم پر فرض کیا گیا ہے اور وہ تم کو (طبعاً) گراں (معلوم ہوتا) ہے۔\" (سورۂ بقرہ، آیت 216)۔ آیات لکھنے کے بعد لکھا ",""],["ٱللَّٰه","a"],[" نے تم سے جو وعدے کیے ہیں وہ سارے ",""],["ٱللَّٰه","a"],[" سے پورے کراؤ (جس کی صورت یہ ہے کہ ",""],["ٱللَّٰه","a"],[" نے ان وعدوں کے لیے جو شرطیں لگائی ہیں تم وہ شرطیں پوری کرو) اور ",""],["ٱللَّٰه","a"],[" نے جو کام تم پر فرض کیے ہیں ان میں ",""],["ٱللَّٰه","a"],[" کی اطاعت کرو، چاہے اس میں کتنی مشقت اٹھانی پڑے اور کتنی زیادہ مصیبتیں برداشت کرنی پڑیں اور کتنے دور دور کے سفر کرنے پڑیں اور کتنے مالی اور جانی نقصانات اٹھانے پڑیں کیونکہ ",""],["ٱللَّٰه","a"],[" کے اجرِ عظیم کے مقابلے میں یہ سب کچھ، کچھ بھی نہیں۔ ",""],["ٱللَّٰه","a"],[" تم پر رحم کرے، تم ہلکے ہو یا بھاری ہر حال میں ",""],["ٱللَّٰه","a"],[" کے راستے میں نکلو اور مال و جان لے کر خوب جہاد کرو۔ پھر اس کے متعلق آیات لکھیں، پھر لکھا غور سے سنو! میں نے حضرت خالد بن ولیدؓ کو عراق جانے کا حکم دیا ہے اور کہا ہے کہ وہاں جا کر میرے دوسرے حکم کا انتظار کرے، لہٰذا آپ لوگ سب ان کے ساتھ جاؤ اور ان کا ساتھ چھوڑ کر زمین سے مت چمٹو کیونکہ یہ ایسا راستہ ہے جس میں ",""],["ٱللَّٰه","a"],[" تعالیٰ اس آدمی کو بہت بڑا اجر عطا فرماتے ہیں جس کی نیت اچھی ہو اور جسے خیر کے کاموں کا بہت زیادہ شوق ہو۔ جب آپ لوگ عراق پہنچ جاؤ تو میرے حکم کے آنے تک وہیں رہو۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ ہماری اور تمہاری دنیا اور آخرت کے تمام ضروری کاموں کی کفایت فرمائے۔ والسلام علیکم ورحمۃ ",""],["ٱللَّٰه","a"],[" وبرکاتہ۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi in his Sunan (Vol.9 Pg.179)."]]},{"b":[["n",[["اور سختیاں تکلیفیں برداشت کرنے کے باب میں، ہجرت کے باب میں، نصرت کے باب میں اور جہاد کے باب وغیرہ میں صحابہؓ کے سختیاں اور تکلیفیں برداشت کرنے کے قصے تفصیل سے گزر چکے ہیں۔",""]]]],"f":[]}]},"285":{"lead":[],"stories":[{"b":[["n",[["حضرت عتبہ بن عبد سلمیؓ","b"],[" فرماتے ہیں نبی کریمؐ نے اپنے صحابہؓ سے فرمایا اٹھو اور (ان کافروں سے) جنگ کرو۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ضرور، ہم بالکل تیار ہیں اور ہم وہ نہیں کہیں گے جو بنی اسرائیل نے حضرت موسیٰ علیہ السلام سے کہا تھا کہ آپ جائیں اور آپ کا رب جائے اور آپ دونوں جنگ کریں، ہم تو یہاں بیٹھے ہیں، بلکہ ہم تو یہ عرض کریں گے کہ اے محمدؐ! آپ جائیں اور آپؐ کا رب جائے، ہم بھی آپ کے ساتھ رہ کر جنگ کریں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.75)."]]},{"b":[["n",[["جہاد کے باب میں ",""],["حضرت مقدادؓ","b"],[" کا اسی جیسا قول گزر چکا ہے جسے ابن ابی حاتم اور ابن مردویہ وغیرہ نے روایت کیا ہے اور حضرت سعد بن عبادہؓ کا یہ قول بھی جلد اول صفحہ نمبر 445 پر گزر چکا ہے کہ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! اگر آپ ہمیں اپنی سواریاں سمندروں میں ڈالنے کا حکم دیں تو ہم ڈال دیں گے اور اگر آپ ہمیں اس بات کا حکم دیں کہ ہم برک الغماد تک اپنی سواریوں پر سفر کریں تو ہم ایسا ضرور کریں گے۔ اور اسی طرح حضرت انسؓ کی روایت سے مسند احمد میں اور حضرت علقمہ بن وقاص لیثیؓ کی روایت سے ابن مردویہ کی کتاب میں حضرت سعد بن معاذؓ کا یہ قول گزر چکا ہے کہ اس ذات کی قسم جس نے آپ کو یہ شرف بخشا اور آپ پر کتاب نازل فرمائی! نہ تو میں کبھی اس راستہ پر چلا ہوں اور نہ مجھے اس کا کچھ علم ہے لیکن آپ اگر یمن کے برک الغماد تک جائیں گے تو ہم بھی آپ کے ساتھ ساتھ وہاں تک ضرور جائیں گے اور ہم ان لوگوں کی طرح نہیں ہوں گے جنہوں نے حضرت موسیٰ علیہ السلام سے کہہ دیا تھا",""]]],["q",[["﴿اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هٰهُنَا قَاعِدُوْنَ﴾","a"]]],["p",[["ترجمہ: \"آپ جائیں اور آپ کا رب بھی جائے، آپ دونوں لڑائی کریں، ہم تو یہاں بیٹھے ہیں۔\" بلکہ ہم تو یہ کہتے ہیں",""]]],["q",[["اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا مَعَكُمْ مُّتَّبِعُوْنَ","a"]]],["p",[["ترجمہ: \"آپ بھی جائیں اور آپ کا رب بھی جائے، آپ دونوں لڑائی کریں اور ہم بھی آپ کے ساتھ ساتھ ہیں۔\" ہو سکتا ہے کہ آپ تو کسی اور کام کے ارادے سے چلے ہوں اور اب ",""],["ٱللَّٰه","a"],[" تعالیٰ کچھ اور کام کروانا چاہتے ہوں یعنی آپ تو قافلۂ ابوسفیان کے مقابلے کے ارادے سے چلے تھے لیکن اب ",""],["ٱللَّٰه","a"],[" تعالیٰ چاہتے ہیں کہ کافروں کے اس لشکر سے لڑا جائے، تو جو ",""],["ٱللَّٰه","a"],[" تعالیٰ کروانا چاہتے ہیں آپ اسے دیکھیں اور اسے کریں۔ اس لیے اب (ہماری طرف سے آپ کو ہر طرح کا پورا اختیار ہے) آپ جس سے چاہیں تعلقات بنائیں اور جس سے چاہیں تعلقات ختم کر دیں اور جس سے چاہیں دشمنی رکھیں اور جس سے چاہیں صلح کر لیں اور ہمارا مال جتنا چاہیں لے لیں۔ چنانچہ حضرت سعدؓ کے اس جواب پر یہ قرآن نازل ہوا",""]]],["q",[["﴿كَمَا أَخْرَجَكَ رَبُّكَ مِنْ بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيْقًا مِّنَ الْمُؤْمِنِيْنَ لَكٰرِهُوْنَ﴾","a"]]],["p",[["ترجمہ: \"جیسا کہ آپ کے رب نے آپ کے گھر (اور بستی) سے مصلحت کے ساتھ آپ کو (بدر کی طرف) روانہ کیا اور مسلمانوں کی ایک جماعت اس کو گراں سمجھتی تھی۔\" (سورۂ انفال، آیت 5)۔ اموی نے اپنی مغازی میں اس حدیث کو ذکر کیا ہے اور اس میں یہ مضمون مزید ہے کہ آپ ہمارا جتنا مال چاہیں لے لیں اور جتنا مال چاہیں ہمیں دے دیں اور جو مال آپ ہم سے لیں گے وہ ہمیں اس سے زیادہ محبوب ہوگا جو آپ ہمارے پاس چھوڑ دیں گے اور آپ جو حکم دیں گے ہمارا معاملہ اس حکم کے تابع ہوگا۔",""]]]],"f":[]}]},"286":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عوف بن احمرؒ","b"],[" کہتے ہیں جب حضرت علی بن ابی طالبؓ انبار شہر سے نہروان والوں کی طرف جانے لگے تو مسافر بن عوف بن احمر نے ان سے کہا اے امیر المومنین! آپ اس گھڑی میں نہ چلیں بلکہ جب دن چڑھے کو تین گھڑیاں گزر جائیں پھر یہاں سے چلیں۔ حضرت علیؓ نے پوچھا کیوں؟ اس نے کہا اگر آپ اس گھڑی میں چلیں گے تو آپ کو اور آپ کے ساتھیوں کو بہت تکلیفیں آئیں گی اور سخت نقصان ہوگا اور اگر آپ اس گھڑی میں سفر شروع کریں جو میں نے بتائی ہے تو آپ کامیاب ہوں گے اور دشمن پر غلبہ پائیں گے اور آپ کو مقصد حاصل ہو جائے گا۔ حضرت علیؓ نے فرمایا نہ تو حضرت محمدؐ کا کوئی نجومی تھا اور نہ ان کے بعد ہمارے ہاں اب تک کوئی تھا۔ کیا تمہیں معلوم ہے کہ میری اس گھوڑی کے پیٹ میں کیا ہے؟ اس نے کہا اگر میں حساب لگاؤں تو پتہ چلا سکتا ہوں۔ حضرت علیؓ نے فرمایا جو تمہاری اس بات کو سچا مانے گا وہ قرآن کو جھٹلانے والا ہوگا کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا",""]]],["q",[["﴿إِنَّ اللّٰهَ عِنْدَهٗ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ﴾","a"]]],["p",[["ترجمہ: \"بے شک ",""],["ٱللَّٰه","a"],[" ہی کو قیامت کی خبر ہے اور وہی مینہ برساتا ہے اور وہی جانتا ہے جو کچھ رحم میں ہے۔\" (سورۂ لقمان، آیت 34)۔ جس چیز کے جاننے کا تم نے دعویٰ کیا ہے اس کے جاننے کا تو حضرت محمدؐ نے بھی دعویٰ نہیں کیا تھا۔ اور کیا تم یہ بھی کہتے ہو کہ تم اس گھڑی کو بھی جانتے ہو جس میں سفر شروع کرنے والے کو نقصان ہوگا؟ اس نے کہا ہاں، میں جانتا ہوں۔ حضرت علیؓ نے فرمایا جو تمہاری اس بات کو سچا مان لے گا اسے تو ناگواریوں اور پریشانیوں کے دور کرنے میں ",""],["ٱللَّٰه","a"],[" کی ضرورت نہیں رہے گی اور جو تمہاری اس بات کو مان لے گا وہ تو اپنے رب ",""],["ٱللَّٰه","a"],[" کو چھوڑ کر اپنا ہر کام تمہارے سپرد کر دے گا کیونکہ تم دعویٰ کر رہے ہو کہ تم وہ گھڑی جانتے ہو جس میں سفر شروع کرنے والا ہر شر اور تکلیف سے محفوظ رہے گا، لہٰذا اس بات پر جو ایمان لے آئے گا مجھے تو اس کے بارے میں یہی خطرہ ہے کہ وہ اس آدمی کی طرح ہو جائے گا جو ",""],["ٱللَّٰه","a"],[" کے علاوہ کسی اور کو ",""],["ٱللَّٰه","a"],[" کا مقابل اور ہمسر بنا لے۔ اے ",""],["ٱللَّٰه","a"],["! اچھا اور برا شگون وہی ہے جو تو نے مقدر فرمایا ہے اور خیر وہی ہے جو تو عطا فرمائے اور تیرے علاوہ اور کوئی معبود نہیں۔ (اے مسافر! ہم تجھے جھٹلاتے ہیں، لہٰذا ہم تیری مخالفت کریں گے اور ہم اسی گھڑی میں سفر شروع کریں گے جس میں سفر کرنے سے تو منع کر رہا ہے۔) پھر حضرت علیؓ نے لوگوں کی طرف متوجہ ہو کر فرمایا اے لوگو! ان ستاروں کا علم سیکھنے سے بچو، البتہ ستاروں کا صرف اتنا علم سیکھو جس سے خشکی اور سمندر کی تاریکی میں راستہ معلوم ہو سکے۔ نجومی تو کافر کی طرح ہے اور کافر جہنم میں جائے گا۔ (پھر مسافر کی طرف متوجہ ہو کر فرمایا) ",""],["ٱللَّٰه","a"],[" کی قسم! اگر مجھے یہ خبر ملی کہ تو ستاروں کو دیکھ کر ان کے مطابق عمل کرتا ہے تو جب تک تو زندہ رہا اور میں زندہ رہا اس وقت تک میں تجھے قید میں رکھوں گا اور جب تک میری خلافت رہے گی تجھے وظیفہ نہیں دوں گا۔ پھر حضرت علیؓ نے اسی گھڑی میں سفر شروع کیا جس سے مسافر نے منع کیا تھا اور جا کر نہروان والوں پر غلبہ پا کر انہیں قتل کیا۔ پھر فرمایا اگر ہم اس گھڑی میں سفر شروع کرتے جس کا مسافر کہہ رہا تھا اور پھر ہم کامیاب ہوتے اور دشمن پر غالب آتے تو لوگ یہی کہتے کہ نجومی نے جس گھڑی میں سفر شروع کرنے کو کہا تھا اس گھڑی میں حضرت علیؓ نے سفر شروع کیا تھا اس وجہ سے دشمن پر غالب آ گئے۔ حضرت محمدؐ کے ہاں کوئی نجومی نہیں تھا اور ان کے بعد ہمارے ہاں بھی کوئی نہیں تھا لیکن پھر بھی ",""],["ٱللَّٰه","a"],[" تعالیٰ نے کسریٰ اور قیصر کے ملکوں پر اور دوسرے ملکوں پر ہمیں فتح فرمائی۔ اے لوگو! ",""],["ٱللَّٰه","a"],[" پر توکل کرو اور اسی پر اعتماد کرو کیونکہ ",""],["ٱللَّٰه","a"],[" جس کے کام بنائے گا اسے کسی اور کی ضرورت نہیں رہے گی۔",""],[" (1)","s"]]]],"f":[["(1)","Haarith, and Khateeb in his Kitaabun Nujoom, as quoted in Kanzul Ummaal (Vol.5 Pg.235)."]]}]},"287":{"lead":[],"stories":[{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" کہتے ہیں حضرت ابوعبیدہ بن جراحؓ ہمارے ساتھ ملک شام میں تھے۔ حضرت عمر بن خطابؓ وہاں تشریف لائے تھے۔ حضرت عمرؓ کے ساتھ اور صحابہؓ بھی چل رہے تھے۔ چلتے چلتے راستہ میں پانی کا ایک گھاٹ آ گیا۔ حضرت عمرؓ اپنی اونٹنی پر سوار تھے۔ وہ اونٹنی سے نیچے اترے اور موزے اتار کر اپنے کندھے پر رکھ لیے اور اپنی اونٹنی کی نکیل پکڑ کر اس گھاٹ میں سے گزرنے لگے تو حضرت ابوعبیدہؓ نے عرض کیا اے امیر المومنین! آپ یہ کیا کر رہے ہیں کہ موزے اتار کر کندھے پر رکھ لیے ہیں اور اونٹنی کی نکیل پکڑ کر اس گھاٹ میں سے گزرنے لگے ہیں؟ مجھے اس بات سے بالکل خوشی نہیں ہوگی کہ اس شہر والے آپ کو (اس حال میں) دیکھیں۔ حضرت عمرؓ نے فرمایا اوہو، اے ابوعبیدہ! اگر آپ کے علاوہ کوئی اور یہ بات کہتا تو میں اسے ایسی سخت سزا دیتا جس سے حضرت محمدؐ کی ساری امت کو عبرت ہوتی۔ ہم تو سب سے زیادہ ذلیل قوم تھے، ",""],["ٱللَّٰه","a"],[" نے ہمیں اسلام کی عزت عطا فرمائی۔ اب جس اسلام کے ذریعہ ",""],["ٱللَّٰه","a"],[" نے ہمیں عزت عطا فرمائی ہے ہم جب بھی اس کے علاوہ کسی اور چیز سے عزت حاصل کرنا چاہیں گے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمیں ذلیل کر دیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.1 Pg.61), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" کہتے ہیں جب حضرت عمرؓ شام پہنچے تو (شام کے) لشکر حضرت عمرؓ کو ملنے کے لیے آئے۔ اس وقت حضرت عمرؓ نے چادر باندھی ہوئی تھی اور موزے پہنے ہوئے تھے اور پگڑی باندھی ہوئی تھی اور اپنے اونٹ کی نکیل پکڑ کر پانی میں سے گزر رہے تھے تو حضرت عمرؓ سے ایک آدمی نے کہا اے امیر المومنین! (شام کے) لشکر اور شام کے جرنیل آپ سے ملنے کے لیے آئے ہیں اور آپ کا یہ حال ہے۔ حضرت عمرؓ نے فرمایا ہمیں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اسلام کے ذریعہ سے عزت دی ہے، لہٰذا ہم اسلام کے علاوہ کسی اور چیز میں عزت تلاش نہیں کر سکتے۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.1 Pg.62)."]]},{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" کہتے ہیں حضرت ابوعبیدہ بن جراحؓ نے حضرت عمرؓ کی خدمت میں عرض کیا اے امیر المومنین! آپ نے تو ایسا کام کر دیا ہے جو اس علاقہ والوں کے نزدیک بہت بڑا (یعنی بڑے عیب والا) کام ہے۔ آپ نے اپنے موزے اتار دیے ہیں اور اپنی سواری (سے نیچے اتر کر) اس کی نکیل پکڑ رکھی ہے اور بے تکلف گھاٹ میں گھس گئے ہیں۔ حضرت عمرؓ نے حضرت ابوعبیدہؓ کے سینے پر ہاتھ مار کر فرمایا اوہو، اے ابوعبیدہ! کاش یہ بات تمہارے علاوہ کوئی اور کہتا۔ تمہاری تعداد لوگوں میں سب سے کم تھی اور تم لوگوں میں سب سے زیادہ ذلیل تھے، ",""],["ٱللَّٰه","a"],[" نے اسلام کے ذریعہ تمہیں عزت عطا فرمائی تو اب جب بھی تم اسلام کے علاوہ کسی اور چیز میں عزت تلاش کرو گے، ",""],["ٱللَّٰه","a"],[" تمہیں ذلیل کر دیں گے۔",""],[" (3)","s"]]]],"f":[["(3)","Haakim (Vol.3 Pg.82). Abu Nu'aym in his Hilya (Vol.1 Pg.47) has reported a similar narration, as have Ibn Mubaarak, Hannaad and Bayhaqi, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.400)."]]},{"b":[["n",[["حضرت قیسؒ","b"],[" کہتے ہیں جب حضرت عمرؓ شام تشریف لائے تو وہ اونٹ پر سوار تھے۔ تمام لوگ ان کے استقبال کے لیے باہر آئے۔ لوگوں نے کہا یہاں کے بڑے اور ممتاز لوگ آپ سے ملنے آئیں گے، اس لیے اچھا یہ ہے کہ آپ ترکی گھوڑے پر سوار ہو جائیں۔ حضرت عمرؓ نے فرمایا بالکل نہیں۔ پھر آسمان کی طرف اشارہ کر کے فرمایا تم لوگ عزت یہاں سے یعنی زمین کے سامان سے سمجھتے ہو، حالانکہ عزت تو وہاں سے (یعنی ",""],["ٱللَّٰه","a"],[" کے دینے سے) ملتی ہے۔ میرے اونٹ کا راستہ چھوڑ دو۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.47)."]]},{"b":[["n",[["حضرت ابوالعالیہ شامیؒ","b"],[" کہتے ہیں جب حضرت عمر بن خطابؓ بیت المقدس کے راستہ میں جابیہ شہر میں پہنچے تو وہ ایک خاکی اونٹ پر سوار تھے اور ان کے سر کا وہ حصہ دھوپ میں چمک رہا تھا جہاں سے بال اتر گئے تھے۔ ان کے سر پر نہ ٹوپی تھی اور نہ پگڑی۔ اور رکاب نہ ہونے کی وجہ سے ان کے دونوں پاؤں کجاوے کے دونوں طرف ہل رہے تھے۔ انبجان شہر کی اونی چادر اونٹ پر ڈالی ہوئی تھی، جب اونٹ پر سوار ہوتے تو اسے اونٹ پر ڈال لیتے اور جب نیچے اترتے تو اسے بچھونا بنا لیتے اور ان کا تھیلہ ایک دھاری دار چادر تھی جس میں کھجور کی چھال بھری ہوئی تھی، جب سوار ہوتے تو اسے تھیلا بنا لیتے اور جب سواری سے اترتے تو اسے تکیہ بنا لیتے اور انہوں نے دھاری دار کھدر کا کرتہ پہنا ہوا تھا جس کا ایک پہلو پھٹا ہوا تھا۔ حضرت عمرؓ نے فرمایا میرے پاس قوم کے سردار کو بلا کر لاؤ۔ لوگ وہاں کے پادریوں کے سردار کو بلا کر لائے۔ حضرت عمرؓ نے فرمایا میرے اس کرتے کو سی کر دھو دو اور اتنی دیر کے لیے کوئی کپڑا یا کرتہ عاریۃً دے دو۔ وہ پادری کتان کپڑے کا کرتہ لے آیا۔ حضرت عمرؓ نے پوچھا یہ کونسا کپڑا ہے؟ لوگوں نے بتایا یہ کتان ہے۔ حضرت عمرؓ نے پوچھا کتان کپڑا کیا ہوتا ہے؟ لوگوں نے اس کپڑے کی تفصیل بتائی۔ حضرت عمرؓ نے اپنا کرتہ اتار کر اسے دیا۔ اس نے اس میں پیوند لگایا اور دھو کر لے آیا۔ حضرت عمرؓ نے ان کا جو کرتہ پہن رکھا تھا وہ اتار کر انہیں دے دیا اور اپنا کرتہ پہن لیا۔ اس پادری نے حضرت عمرؓ سے کہا آپ عربوں کے بادشاہ ہیں، ہمارے اس علاقے میں اونٹ کی سواری ٹھیک نہیں (اور نہ آپ کا یہ کرتہ ٹھیک ہے)، اس لیے اگر آپ کسی اور اچھے کپڑے کا کرتہ پہن لیں اور ترکی گھوڑے کی سواری کریں، اس سے رومیوں کی نگاہ میں آپ کی قدر و منزلت بڑھ جائے گی۔ حضرت عمرؓ نے فرمایا ہم لوگوں کو ",""],["ٱللَّٰه","a"],[" نے اسلام کے ذریعے عزت عطا فرمائی ہے، لہٰذا ",""],["ٱللَّٰه","a"],[" کے (دین کے) علاوہ کسی اور کا ہم سوچ بھی نہیں سکتے۔ اس کے بعد ان کی خدمت میں ایک ترکی گھوڑا لایا گیا۔ اس پر کاٹھی اور کجاوے کے بغیر ہی ایک موٹی چادر ڈال دی گئی۔ وہ اس پر سوار ہوئے (وہ گھوڑا اکڑ کر چلنے لگا تو) حضرت عمرؓ نے فرمایا اسے روکو، اسے روکو (کیونکہ یہ شیطان کی طرح چل رہا ہے)۔ اس سے پہلے میں نے لوگوں کو شیطان پر سوار ہوتے ہوئے کبھی نہیں دیکھا تھا۔ پھر ان کا اونٹ لایا گیا اور وہ گھوڑے سے اتر کر اسی پر سوار ہو گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.47)."]]}]},"288":{"lead":[],"stories":[{"b":[["n",[["حضرت ابونہیک اور حضرت عبد","b"],["ٱللَّٰه","a"],[" بن حنظلہؒ","b"],[" کہتے ہیں ہم ایک لشکر میں حضرت سلمانؓ کے ساتھ تھے۔ ایک آدمی نے سورت مریم پڑھی تو دوسرے آدمی نے حضرت مریم اور ان کے بیٹے (حضرت عیسیٰ) علیہما السلام کو برا بھلا کہا (بظاہر یہ آدمی یہودی ہوگا)۔ ہم نے اسے مار مار کر لہولہان کر دیا۔ جس انسان پر ظلم ہوتا تھا وہ جا کر حضرت سلمانؓ سے شکایت کرتا تھا۔ چنانچہ اس آدمی نے بھی جا کر حضرت سلمانؓ سے شکایت کر دی۔ اس سے پہلے اس نے کبھی ان سے کوئی شکایت نہیں کی تھی۔ حضرت سلمانؓ ہمارے پاس تشریف لائے اور فرمایا تم نے اس آدمی کو کیوں مارا ہے؟ ہم نے کہا ہم نے سورت مریم پڑھی تھی، اس نے حضرت مریمؑ اور ان کے بیٹے کو برا بھلا کہا۔ انہوں نے فرمایا تم لوگوں نے انہیں سورت مریم کیوں سنائی؟ کیا آپ لوگوں نے ",""],["ٱللَّٰه","a"],[" کا یہ فرمان نہیں سنا؟",""]]],["q",[["﴿وَلَا تَسُبُّوا الَّذِيْنَ يَدْعُوْنَ مِنْ دُوْنِ اللّٰهِ فَيَسُبُّوا اللّٰهَ عَدْوًا بِغَيْرِ عِلْمٍ﴾","a"]]],["p",[["ترجمہ: \"اور دشنام مت دو ان کو جن کی یہ لوگ خدا کو چھوڑ کر عبادت کرتے ہیں کیونکہ پھر وہ براہِ جہل حد سے گزر کر ",""],["ٱللَّٰه","a"],[" کی شان میں گستاخی کریں گے۔\" (سورۂ انعام، آیت 108)۔ اے جماعتِ عرب! کیا آپ لوگوں کا مذہب سب سے زیادہ برا نہیں تھا؟ آپ لوگوں کا علاقہ سب سے برا نہیں تھا؟ کیا آپ لوگوں کی زندگی سب سے زیادہ بری نہیں تھی؟ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپ لوگوں کو عزت دی اور آپ لوگوں کو سب کچھ دیا۔ کیا آپ لوگ یہ چاہتے ہو کہ ",""],["ٱللَّٰه","a"],[" کی دی ہوئی عزت کی وجہ سے لوگوں کی پکڑ کرتے رہو؟ ",""],["ٱللَّٰه","a"],[" کی قسم! یا تو آپ لوگ اس کام سے باز آ جاؤ ورنہ جو کچھ آپ لوگوں کے ہاتھ میں ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے تم سے لے کر دوسروں کو دے دیں گے۔ پھر حضرت سلمانؓ ہمیں سکھانے لگے اور فرمایا مغرب اور عشاء کے درمیان نوافل پڑھا کرو کیونکہ ان نوافل میں بہت سا قرآن پڑھ لینے کی وجہ سے تمہارے روز کے قرآن پڑھنے کی مقررہ مقدار میں کمی ہو جائے گی اور اس طرح رات کا شروع کا حصہ بے کار ہونے سے بچ جائے گا کیونکہ جس کا رات کا شروع کا حصہ بے کار گزر جائے گا تو اس کا رات کا آخری حصہ یعنی تہجد کا وقت بھی بیکار گزرے گا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.201)."]]}]},"289":{"lead":[],"stories":[{"b":[["n",[["حضرت جبیر بن نفیرؓ","b"],[" فرماتے ہیں جب قبرص جزیرہ فتح ہوا تو وہاں کے رہنے والے سارے غلام بنا لیے گئے اور انہیں مسلمانوں میں تقسیم کر دیا گیا۔ وہ ایک دوسرے کی جدائی پر رو رہے تھے۔ میں نے دیکھا کہ حضرت ابوالدرداءؓ اکیلے بیٹھے ہوئے رو رہے ہیں۔ میں نے پوچھا اے ابوالدرداء! آج تو ",""],["ٱللَّٰه","a"],[" نے اسلام اور اہلِ اسلام کو عزت عطا فرمائی ہے تو آپ کیوں رو رہے ہیں؟ فرمایا اے جبیر! تیرا بھلا ہو، اس مخلوق نے جب ",""],["ٱللَّٰه","a"],[" کے حکم کو چھوڑ دیا تو یہ ",""],["ٱللَّٰه","a"],[" کے ہاں کتنی بے قیمت ہو گئی۔ پہلے تو یہ زبردست اور غالب قوم تھی اور انہیں بادشاہت حاصل تھی لیکن انہوں نے ",""],["ٱللَّٰه","a"],[" کا حکم چھوڑ دیا تو اب ان کا وہ برا حال ہو گیا جو تم دیکھ رہے ہو۔ ابن جریر کی روایت میں اس کے بعد یہ بھی ہے کہ اب تو ان کا وہ برا حال ہو گیا جو تم دیکھ رہے ہو کہ ان پر ",""],["ٱللَّٰه","a"],[" نے غلامی مسلط کر دی اور جب کسی قوم پر ",""],["ٱللَّٰه","a"],[" غلامی مسلط کر دیں تو سمجھ لو کہ ",""],["ٱللَّٰه","a"],[" کو ان کی کوئی ضرورت نہیں (کیونکہ ان کی ",""],["ٱللَّٰه","a"],[" کے ہاں کوئی قیمت نہیں رہی)۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.216). Ibn Jareer (Vol.3 Pg.318) has reported the addition."]]}]},"290":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن ابی مریمؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ حضرت معاذ بن جبلؓ کے پاس سے گزرے تو حضرت عمرؓ نے فرمایا وہ اعمال کونسے ہیں جن سے اس امت کے سارے کام ٹھیک رہتے ہیں؟ حضرت معاذؓ نے کہا تین اعمال ہیں اور تینوں نجات دلانے والے ہیں: ایک اخلاص اور اخلاص وہ عملِ فطرت ہے جس پر ",""],["ٱللَّٰه","a"],[" نے لوگوں کو پیدا کیا ہے، اور دوسرا عمل نماز ہے اور وہ مذہب کا اہم شعبہ ہے، اور تیسرا عمل (امیر کی) اطاعت ہے اور اطاعت ہی بچاؤ کا سامان ہے۔ حضرت عمرؓ نے فرمایا آپ نے ٹھیک کہا۔ جب حضرت عمرؓ وہاں سے آگے چلے گئے تو حضرت معاذؓ نے اپنے پاس بیٹھنے والوں سے فرمایا غور سے سنو! (اے عمرؓ!) آپ کا زمانہ بعد والوں کے زمانے سے بہتر ہے کیونکہ آپ کے بعد امت میں اختلاف ہو جائے گا (اور سنو) اب یہ حضرت عمرؓ بھی دنیا میں تھوڑا عرصہ ہی رہیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.8 Pg.226)."]]},{"b":[["n",[["حضرت ابوعبیدہ العنبریؒ","b"],[" کہتے ہیں جب مسلمان مدائن فتح کر کے اس میں داخل ہوئے اور مالِ غنیمت جمع کرنے لگے تو ایک آدمی اپنے ساتھ ایک ڈبہ لایا اور لا کر مالِ غنیمت جمع کرنے والے ذمہ دار کو دے دیا۔ اس ذمہ دار کے ساتھیوں نے کہا اس ڈبہ جیسا قیمتی سامان تو ہم نے کبھی دیکھا نہیں (کیونکہ بادشاہ نے اس میں سب سے زیادہ قیمتی ہیرے جواہرات رکھے ہوئے تھے) اور ہمارے پاس جتنا مالِ غنیمت آ چکا ہے اس سب کی قیمت اس کے برابر تو کیا اس کے قریب بھی نہیں ہو سکتی۔ پھر ان لوگوں نے لانے والے سے پوچھا کیا آپ نے اس میں سے کچھ لیا ہے؟ اس نے کہا غور سے سنو، ",""],["ٱللَّٰه","a"],[" کی قسم! اگر ",""],["ٱللَّٰه","a"],[" کا ڈر نہ ہوتا تو میں اسے آپ لوگوں کے پاس کبھی نہ لاتا۔ اس جواب سے وہ لوگ سمجھ گئے کہ یہ آدمی بڑی شان والا ہے۔ انہوں نے پوچھا آپ کون ہیں؟ فرمایا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! نہیں۔ اپنے بارے میں میں نہ تو آپ لوگوں کو بتاؤں گا کیونکہ آپ لوگ میری تعریف کرنے لگ جائیں گے اور نہ کسی اور کو بتاؤں گا کیونکہ پھر لوگ میری سچی جھوٹی تعریف کرنے لگ جائیں گے، بلکہ میں تو ",""],["ٱللَّٰه","a"],[" تعالیٰ کی تعریف بیان کرتا ہوں اور اس کے ثواب پر راضی ہوں۔ (پھر وہ آدمی چلا گیا) تو ان لوگوں نے ایک آدمی اس کے پیچھے بھیجا۔ وہ آدمی (اس کے پیچھے چلتے چلتے) اس کے ساتھیوں کے پاس پہنچ گیا۔ پھر اس نے اس کے ساتھیوں سے اس کے بارے میں پوچھا تو وہ حضرت عامر بن عبد قیس رحمتہ ",""],["ٱللَّٰه","a"],[" علیہ نکلے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer (Vol.3 Pg.128)."]]},{"b":[["n",[["حضرت محمد، حضرت طلحہ اور حضرت مہلب","b"],[" وغیرہ حضرات کہتے ہیں (قادسیہ کی جنگ کے موقع پر) حضرت سعدؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! یہ لشکر بڑا امانتدار ہے۔ اگر بدر والوں کو پہلے فضیلت نہ ملی ہوتی تو ",""],["ٱللَّٰه","a"],[" کی قسم! میں کہتا اس لشکر کی بھی بدر والوں جیسی فضیلت ہے۔ بہت سی قوموں کو میں نے غور سے دیکھا، ان میں مالِ غنیمت جمع کرنے کے بارے میں بہت سی کمزوریاں نظر آئیں لیکن میرے خیال میں اس لشکر والوں میں ایسی کوئی کمزوری نہیں اور نہ میں نے ان کی کسی کمزوری کے بارے میں کسی سے کچھ سنا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Jareer (Vol.3 Pg.128)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں اس ",""],["ٱللَّٰه","a"],[" کی قسم جس کے سوا کوئی معبود نہیں! قادسیہ والوں میں سے کسی کے بارے میں ہمیں یہ اطلاع نہیں ملی کہ وہ آخرت کے ساتھ ساتھ دنیا بھی چاہتا ہو، البتہ ہمیں (ہزاروں کے لشکر میں) صرف تین آدمیوں کے بارے میں شبہ ہوا (کہ شاید یہ دنیا بھی چاہتے ہوں) لیکن تحقیق کرنے پر وہ بھی امانتدار اور بڑے زاہد نکلے۔ وہ تین حضرات یہ ہیں: حضرت طلحہ بن خویلد، حضرت عمرو بن معدیکرب اور حضرت قیس بن مکشوحؓ۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Jareer (Vol.3 Pg.128)."]]},{"b":[["n",[["حضرت قیس عجلیؒ","b"],[" کہتے ہیں جب حضرت عمرؓ کے پاس کسریٰ کی تلوار، کمر کی پٹی اور زیب و زینت کا سامان لایا گیا تو حضرت عمرؓ نے فرمایا جن لوگوں نے یہ سارا کا سارا مالِ غنیمت یہاں پہنچا دیا ہے وہ واقعی بڑے امانتدار ہیں۔ اس پر حضرت علیؓ نے فرمایا چونکہ آپ خود پاکدامن ہیں، اس لیے رعایا بھی پاکدامن ہو گئی۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Jareer (Vol.3 Pg.128)."]]}]},"291":{"lead":[],"stories":[{"b":[["n",[["حضرت زید بن اسلمؒ","b"],[" کہتے ہیں جب حضرت عمر بن خطابؓ نے دیکھا کہ مصر فتح ہونے میں دیر لگ رہی ہے تو انہوں نے حضرت عمرو بن عاصؓ کو یہ خط لکھا: \"اما بعد! مجھے اس بات پر بہت تعجب ہے کہ مصر کی فتح میں آپ لوگوں کو دیر لگ رہی ہے۔ آپ ان سے کئی سالوں سے لڑ رہے ہیں اور اس کی وجہ صرف یہ ہے کہ آپ لوگوں نے نئے نئے کام شروع کر دیے ہیں اور جیسے آپ لوگوں کے دشمن کو دنیا سے محبت ہے ایسے ہی آپ لوگوں کے دلوں میں بھی دنیا کی محبت آ گئی ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ لوگوں کی مدد صرف ان کی سچی نیت کی وجہ ہی سے کرتے ہیں۔ اور میں نے آپ کے پاس چار آدمی بھیجے ہیں اور آپ کو بتا رہا ہوں کہ میرے علم کے مطابق ان میں سے ہر آدمی ہزار آدمیوں کے برابر ہے، ہاں دنیا کی محبت جس نے دوسروں کو بدلا ہے وہ ان کو بھی بدل دے تو اور بات ہے۔ جب میرا یہ خط آپ کو ملے تو آپ لوگوں میں بیان کریں اور ان کو دشمن سے لڑنے کے لیے ابھاریں اور ان کو صبر کی اور نیت خالص کرنے کی ترغیب دیں اور ان چاروں کو سب لوگوں سے آگے رکھیں اور لوگوں سے کہیں کہ وہ سب اکٹھے مل کر ایک دم دشمن پر حملہ کریں اور یہ حملہ جمعہ کے دن زوال کے وقت کریں کیونکہ یہ ایسی گھڑی ہے جس میں رحمت نازل ہوتی ہے اور دعا قبول ہوتی ہے اور سب ",""],["ٱللَّٰه","a"],[" کے سامنے خوب گڑگڑائیں اور اس سے اپنے دشمن کے خلاف مدد مانگیں۔\" جب یہ خط حضرت عمرو کے پاس پہنچا تو حضرت عمروؓ نے لوگوں کو جمع کر کے یہ خط سنایا، پھر ان چار آدمیوں کو بلا کر لوگوں کے آگے کیا اور پھر لوگوں سے کہا کہ وضو کر کے دو رکعت نماز پڑھیں، پھر ",""],["ٱللَّٰه","a"],[" کی طرف متوجہ ہو کر اس سے مدد مانگیں۔ چنانچہ ایسا کرنے سے ",""],["ٱللَّٰه","a"],[" نے ان کے لیے مصر فتح کر دیا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abdul Hakam, as quoted in Kanzul Ummaal (Vol.3 Pg.151)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن جعفر اور عیاش بن عباس","b"],[" وغیرہ حضرات کچھ کمی بیشی کے ساتھ روایت کرتے ہیں کہ جب حضرت عمرو بن عاصؓ کو مصر فتح کرنے میں دیر لگی تو انہوں نے مدد طلب کرنے کے لیے حضرت عمر بن خطابؓ کو خط لکھا۔ حضرت عمرؓ نے ان کی مدد کے لیے چار ہزار آدمی بھیجے اور ہر ہزار پر ایک آدمی کو امیر بنایا اور ان کو حضرت عمر بن خطاب نے یہ خط لکھا کہ میں آپ کی مدد کے لیے چار ہزار آدمی بھیج رہا ہوں۔ ہر ہزار پر ایک ایسا آدمی مقرر کیا ہے جو ہزار کے برابر ہے۔ وہ چار حضرات یہ ہیں: حضرت زبیر بن عوام، حضرت مقداد بن اسود بن عمرو، حضرت عبادہ بن صامت اور حضرت مسلمہ بن مخلدؓ۔ اور آپ کو معلوم ہونا چاہیے کہ آپ کے ساتھ بارہ ہزار آدمی ہیں اور بارہ ہزار کا لشکر تعداد کی کمی کی وجہ سے مغلوب نہیں ہو سکتا (کسی گناہ کی وجہ سے ہو سکتا ہے)۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abdul Hakam, as quoted in Kanzul Ummaal (Vol.3 Pg.151)."]]},{"b":[["n",[["حضرت عیاض اشعریؒ","b"],[" کہتے ہیں میں جنگِ یرموک میں شریک تھا۔ اس جنگ میں مسلمانوں کے لشکر کے پانچ امیر تھے: حضرت ابوعبیدہ، حضرت یزید بن ابی سفیان، حضرت شرحبیل بن حسنہ، حضرت خالد بن ولید اور حضرت عیاضؓ۔ یہ حضرت عیاض دوسرے صاحب ہیں، اس حدیث کے راوی نہیں ہیں۔ حضرت عمرؓ نے فرمایا جب جنگ ہو تو آپ لوگوں کے امیر حضرت ابوعبیدہؓ ہوا کریں گے۔ پھر ہم نے حضرت عمرؓ کو مدد طلب کرنے کے لیے خط میں یہ لکھا کہ موت بڑے جوش و خروش سے ہماری طرف بڑھ رہی ہے۔ انہوں نے ہمیں جواب میں یہ لکھا کہ مدد طلب کرنے کے لیے آپ لوگوں کا خط میرے پاس آیا۔ میں آپ لوگوں کو ایسی ذات بتاتا ہوں جس کی مدد بڑی زوردار ہے اور جس کا لشکر ہر جگہ موجود ہے اور وہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کی ذات ہے، لہٰذا اسی سے مدد مانگو کیونکہ حضرت محمدؐ کی جنگِ بدر میں مدد ہوئی، حالانکہ ان کی تعداد کم تھی۔ احمد کی روایت میں یہ بھی ہے کہ جب آپ لوگوں کو میرا یہ خط ملے تو آپ لوگ ان سے جنگ کریں اور مجھ سے دوبارہ مدد طلب نہ کریں۔ راوی کہتے ہیں ہم نے ان سے جنگ کی اور انہیں خوب قتل کیا اور انہیں چار فرسخ یعنی بارہ میل تک شکست دی اور ہمیں بہت سا مالِ غنیمت ملا۔ پھر ہم نے مشورہ کیا تو حضرت عیاضؓ نے ہمیں یہ مشورہ دیا کہ ہر مسلمان کے چھڑوانے کے بدلے دس کافر دے دیں۔ راوی کہتے ہیں حضرت ابوعبیدہؓ نے فرمایا گھوڑا دوڑانے میں کون مجھ سے بازی لگاتا ہے؟ اس پر ایک نوجوان نے کہا اگر آپ خفا نہ ہوں تو میں۔ چنانچہ یہ نوجوان دوڑ میں حضرت ابوعبیدہؓ سے آگے نکل گیا۔ میں نے دیکھا کہ حضرت ابوعبیدہؓ بغیر زین کے گھوڑے پر سوار ہیں اور اس نوجوان کے پیچھے دوڑ رہے ہیں اور ان کے بالوں کی دونوں مینڈھیاں زور زور سے ہل رہی ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Kanzul Ummaal (Vol.3 Pg.145). Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.6 Pg.213) and Ibn Katheer in his Tafseer (Vol.1 Pg.400)."]]},{"b":[["n",[["حضرت محمد، حضرت طلحہ اور حضرت زیادؒ","b"],[" اپنی اپنی سند سے بیان کرتے ہیں کہ حضرت عمرؓ نے ایک نوجوان حضرت سعدؓ کے ساتھ مستقل لگا رکھا تھا جو کہ قاریوں میں سے تھا۔ جب حضرت سعدؓ نمازِ ظہر پڑھا چکے تو اس نوجوان کو حکم دیا کہ وہ سورتِ جہاد یعنی سورتِ انفال پڑھے اور تمام مسلمان یہ سورت سیکھے ہوئے تھے۔ چنانچہ لشکر کا جو حصہ قریب تھا اس نوجوان نے اس کے سامنے وہ سورتِ جہاد پڑھی، پھر وہ سورت لشکر کے ہر دستے میں پڑھی گئی جس سے تمام لوگوں کے دلوں میں ذوق شوق بڑھ گیا اور سب نے اس کے پڑھتے ہی سکون محسوس کیا۔ حضرت مسعود بن خراش کی روایت میں یہ ہے کہ لوگ سورتِ جہاد سیکھے ہوئے تھے، اس لیے حضرت سعد نے لوگوں کو حکم دیا کہ وہ ایک دوسرے کے سامنے اسے پڑھیں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Jareer (Vol.3 Pg.47)."]]},{"b":[["n",[["حضرت ابراہیم بن حارث تیمیؓ","b"],[" فرماتے ہیں حضورؐ نے ہمیں ایک لشکر میں بھیجا اور ہمیں حکم دیا کہ ہم صبح اور شام",""]]],["q",[["﴿أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنٰكُمْ عَبَثًا﴾","a"]]],["p",[["(سورۂ مومنون، آیت 115) پڑھا کریں۔ چنانچہ ہم یہ آیت پڑھتے رہے جس سے ہم خود صحیح سالم رہے اور ہمیں مالِ غنیمت بھی ملا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Ma'rifah and Ibn Mandah, as quoted in Kanzul Ummaal (Vol.2 Pg.327) and Isaabah (Vol.1 Pg.15)."]]},{"b":[["n",[["حضرت محمد، حضرت طلحہ اور حضرت زیادؒ","b"],[" اپنی اپنی سند سے یہ بیان کرتے ہیں کہ حضرت سعدؓ نے فرمایا \"آپ سب لوگ اپنی جگہ ٹھہرے رہیں اور ظہر کی نماز پڑھنے تک کچھ حرکت نہ کریں۔ آپ لوگ جب ظہر پڑھ لیں گے تو میں زور سے ",""],["ٱللَّٰه","a"],[" اکبر کہوں گا، اس وقت آپ لوگ بھی ",""],["ٱللَّٰه","a"],[" اکبر کہیں اور تیاری شروع کر دیں اور آپ لوگوں کو معلوم ہونا چاہیے کہ زور سے ",""],["ٱللَّٰه","a"],[" اکبر کہنا آپ لوگوں سے پہلے کسی کو نہیں دیا گیا اور یہ آپ لوگوں کو مضبوط اور طاقتور بنانے کے لیے دیا گیا ہے۔ پھر جب آپ لوگ دوسری مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر سنیں تو آپ لوگ بھی ",""],["ٱللَّٰه","a"],[" اکبر کہیں اور اپنی تیاری مکمل کر لیں۔ پھر جب میں تیسری مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہوں تو آپ لوگ بھی ",""],["ٱللَّٰه","a"],[" اکبر کہیں اور آپ لوگوں میں جو گھوڑے سوار ہیں وہ میدانِ جنگ میں اتر نے اور دشمن پر حملہ کرنے کے لیے پیدل ساتھیوں کا حوصلہ بڑھائیں۔ پھر جب میں چوتھی مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہوں تو آپ سب لوگ اکٹھے چل پڑیں اور دشمن میں گھس جائیں اور لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],[" پڑھتے رہیں۔\"",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Ibn Jareer (Vol.3 Pg.47)."],["(7)","Ibn Jareer (Vol.3 Pg.47)."]]},{"b":[["n",[["حضرت محمد، حضرت طلحہ اور حضرت زیادؒ","b"],[" اپنی اپنی سند سے بیان کرتے ہیں کہ جب قاری حضرات آیاتِ جہاد کی تلاوت سے فارغ ہو گئے تو حضرت سعدؓ نے زور سے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ اسے سن کر ان کے قریب والوں نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ اس طرح ایک دوسرے سے سن کر سارے لوگوں نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ اس سے لوگوں میں حملہ کی تیاری کے لیے حرکت شروع ہو گئی۔ پھر حضرت سعدؓ نے دوبارہ ",""],["ٱللَّٰه","a"],[" اکبر کہا تو لوگوں نے تیاری مکمل کر لی۔ پھر انہوں نے تیسری مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا تو بہادرانِ لشکر آگے بڑھے اور انہوں نے گھمسان کی لڑائی شروع کر دی۔ آگے اور بھی حدیث ذکر کی ہے۔",""]]]],"f":[]}]},"292":{"lead":[],"stories":[{"b":[["n",[["حضرت جعفر بن عبد","b"],["ٱللَّٰه","a"],[" بن حکمؒ","b"],[" کہتے ہیں حضرت خالد بن ولیدؓ نے جنگِ یرموک کے دن اپنی ٹوپی نہ پائی تو ساتھیوں سے فرمایا اسے تلاش کرو۔ انہوں نے تلاش کیا تو انہیں نہ ملی۔ فرمایا اور تلاش کرو۔ اور تلاش کیا گیا تو مل گئی۔ لوگوں نے دیکھا تو وہ بالکل پرانی ٹوپی تھی۔ حضرت خالدؓ نے فرمایا ایک دفعہ حضورؐ نے عمرہ کیا، پھر بال منڈوائے۔ لوگ آپؐ کے بالوں پر جھپٹ پڑے۔ میں نے بھی آگے بڑھ کر آپؐ کی پیشانی کے بال اٹھا لیے اور اس ٹوپی میں رکھ لیے۔ جب میں کسی لڑائی میں شریک ہوتا ہوں اور یہ ٹوپی میرے پاس ہوتی ہے تو مجھے ",""],["ٱللَّٰه","a"],[" کی غیبی نصرت ضرور نصیب ہوتی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani and Abu Ya'la, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.349). Haakim (Vol.3 Pg.299) has reported a similar narration, as has Abu Nu'aym in his Dalaa'il (Pg.159)."]]},{"b":[["n",[["حضرت جعفرؒ","b"],[" کہتے ہیں حضرت خالد بن ولیدؓ کی ٹوپی میں حضورؐ کے چند بال مبارک رکھے ہوئے تھے۔ حضرت خالدؓ نے فرمایا جب بھی میرا کسی لشکر سے مقابلہ ہوتا ہے اور یہ ٹوپی میرے سر پر ہوتی ہے تو مجھے فتح ضرور حاصل ہوتی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.7 Pg.31)."]]}]},"293":{"lead":[],"stories":[{"b":[["n",[["حضرت شقیقؒ","b"],[" کہتے ہیں ہم نے دن کے شروع میں جنگِ قادسیہ میں لڑائی شروع کی۔ جب ہم واپس آئے تو نماز کا وقت ہو چکا تھا اور مؤذن صاحب زخمی ہو چکے تھے، اس لیے ہر مسلمان یہ چاہنے لگا کہ اذان کی سعادت اسے ہی نصیب ہو اور اتنا تقاضا بڑھا کہ قریب تھا کہ آپس میں تلواروں سے لڑ پڑیں۔ آخر حضرت سعدؓ نے ان میں اذان کے لیے قرعہ اندازی کی اور ایک آدمی کا نام قرعہ میں نکلا اور اس نے اذان دی۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer (Vol.3 Pg.70)."]]}]},"294":{"lead":[],"stories":[{"b":[["n",[["حضرت معقل بن یسارؓ","b"],[" حضرت نعمان بن مقرنؓ کی امارت میں اصفہان کے فتح ہونے کے بارے میں لمبی حدیث ذکر کرتے ہیں۔ اس میں یہ بھی ہے کہ حضرت نعمانؓ لشکر لے کر اصفہان کے قریب پہنچے تو ان کے اور اصفہان کے درمیان دریا تھا۔ حضرت نعمانؓ نے حضرت مغیرہ بن شعبہؓ کو قاصد بنا کر اصفہان بھیجنا چاہا۔ ان دنوں اصفہان میں ذوالحاجبین بادشاہ تھا۔ اس نے آنے والے صحابی کو مرعوب کرنے کے لیے اپنے ساتھیوں سے مشورہ کیا کہ کیا میں اپنا دربار فوجی انداز سے سجا کر بیٹھوں یا شاہانہ شان و شوکت سے سجاؤں؟ اس کے ساتھیوں نے شاہانہ شان و شوکت کا مشورہ دیا۔ چنانچہ اس نے شاہی طریقہ سے اپنا دربار سجایا، خود شاہی تخت پر بیٹھا اور سر پر شاہی تاج رکھا اور درباری اس کے گرد دو صفیں بنا کر کھڑے ہو گئے۔ ان لوگوں نے دیباج کے ریشمی کپڑے پہن رکھے تھے، ان کے کانوں میں بالیاں اور ہاتھوں میں کنگن تھے۔ حضرت مغیرہ بن شعبہؓ دربار میں آئے۔ وہ سر جھکائے تیزی سے چل رہے تھے۔ ان کے ہاتھ میں نیزہ اور ڈھال بھی تھی اور لوگ دو صفیں بنائے بادشاہ کے گرد قالین پر کھڑے تھے۔ حضرت مغیرہؓ نیزے پر ٹیک لے کر چل رہے تھے جس سے وہ قالین پھٹ گیا۔ ایسا انہوں نے قصداً کیا تاکہ یہ ان لوگوں کے لیے بدفالی ہو۔ ذوالحاجبین نے ان سے کہا اے جماعتِ عرب! تم لوگ سخت فاقہ اور مشقت میں مبتلا ہو، اس لیے اپنے ملک سے نکل کر ہمارے ہاں آ گئے ہو۔ اگر تم چاہو تو ہم تمہیں غلہ دے دیتے ہیں، اسے لے کر تم اپنے ملک واپس چلے جاؤ۔ پھر حضرت مغیرہؓ نے گفتگو شروع فرمائی۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، پھر فرمایا ہم عرب لوگ واقعی بہت برے تھے، مردار جانور کھایا کرتے تھے اور بڑے کمزور تھے، تمام لوگوں کا ہم پر زور چلتا تھا، ہمارا کسی پر نہیں چلتا تھا۔ پھر ",""],["ٱللَّٰه","a"],[" نے ہم میں ایک رسول بھیجا جو ہمارے شریف خاندان کا تھا، جس کا حسب ہم میں سب سے اعلیٰ تھا، جس کی بات سب سے زیادہ سچی تھی۔ انہوں نے ہم سے وعدہ کیا تھا کہ یہ جگہ فتح ہو کر ہمیں ملے گی اور اب تک ہم ان کے تمام وعدوں کو سچا پا چکے ہیں۔ اور میں یہاں بڑے شاندار کپڑے اور قیمتی سامان دیکھ رہا ہوں، مجھے یقین ہے کہ میرے ساتھی انہیں لیے بغیر یہاں سے نہیں جائیں گے۔ آگے اور بھی حدیث ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.293). Tabraani has reported a similar narration from reliable sources as confirmed by Haythami (Vol.6 Pg.217)."]]},{"b":[["n",[["حضرت محمد، حضرت طلحہ، حضرت عمرو اور حضرت زیادؒ","b"],[" اپنی اپنی سند سے روایت کرتے ہیں کہ حضرت سعدؓ نے آدمی بھیج کر حضرت مغیرہ بن شعبہؓ اور صحابہ کی ایک جماعت کو بلایا اور فرمایا میں آپ لوگوں کو ان لوگوں (رستم وغیرہ) کے پاس بھیجنا چاہتا ہوں، اس بارے میں آپ لوگوں کی کیا رائے ہے؟ ان سب حضرات نے کہا آپ جو حکم فرمائیں گے ہم تابعدار ہیں اور اس پر پکے رہیں گے (یعنی ہم جانے کے لیے تیار ہیں) اور وہاں جا کر جب کوئی ایسا مسئلہ پیش ہوگا جس میں آپ کی طرف سے کوئی فیصلہ نہیں ہوا ہوگا تو ہم اس چیز کے بارے میں غور کریں گے جو زیادہ مناسب اور لوگوں کے لیے زیادہ مفید ہے اور جو سمجھ میں آئے گا وہ ہم ان لوگوں کو بتائیں گے۔ حضرت سعدؓ نے فرمایا عقلمند تجربہ کار لوگ ایسے ہی کیا کرتے ہیں، اب آپ لوگ جائیں اور جانے کی تیاری کریں۔ حضرت ربعی بن عامرؓ نے کہا عجمی لوگوں کے اپنے طور طریقے اور آداب ہیں۔ جب ہم ان کے پاس جائیں گے تو وہ سمجھیں گے کہ ہم نے ان کا بڑا اہتمام کیا ہے، لہٰذا آپ ان کے پاس ایک سے زیادہ آدمی نہ بھیجیں۔ باقی تمام حضرات نے بھی اس بات میں حضرت ربعیؓ کی تائید کی۔ اس کے بعد حضرت ربعیؓ نے کہا آپ سب مجھے بھیج دیں۔ اس پر حضرت سعدؓ نے انہیں بھیجنے کا فیصلہ کر دیا۔ چنانچہ حضرت ربعیؓ رستم کے لشکر گاہ میں اس سے ملنے کے لیے روانہ ہوئے۔ پل پر جو سپاہی مقرر تھے انہوں نے حضرت ربعیؓ کو روک لیا اور ان کے آنے کی اطلاع دینے کے لیے آدمی رستم کے پاس بھیجا۔ رستم نے فارس کے بڑے سرداروں سے مشورہ کیا اور یہ سوال کیا کہ ہم کیا صرف اپنی تعداد کے زیادہ ہونے پر فخر کریں یا شاہی اور قیمتی سامان دکھا کر عربوں کا بے حیثیت ہونا ظاہر کریں اور اس طرح انہیں مرعوب کریں؟ سب کا اسی پر اتفاق ہوا کہ شاہی اور قیمتی سامان کا مظاہرہ کیا جائے۔ چنانچہ خزانے سے نکال کر انہوں نے زیب و زینت کا سارا سامان سجا ڈالا اور ہر طرف قیمتی گدے، بچھونے اور قالین بچھا دیے اور خزانے میں کوئی چیز نہ رہنے دی۔ رستم کے لیے سونے کا تخت رکھا گیا، اسے بیش قیمت شاندار کپڑے پہنائے گئے اور قیمتی قالین بچھائے گئے اور ایسے تکیے رکھے گئے جو سونے کی تاروں سے بنے ہوئے تھے۔ (حضرت ربعیؓ کو پل کے سپاہیوں نے آگے جانے کی اجازت دے دی تو) حضرت ربعیؓ اپنے گھوڑے پر چل پڑے۔ گھوڑے کے بال زیادہ اور قد چھوٹا تھا۔ ان کے پاس ایک چمکدار تلوار تھی اور اسے پرانے کپڑے میں لپیٹا ہوا تھا اور ان کے نیزے پر چمڑے کے تسمے بندھے ہوئے تھے اور ان کے پاس گائے کی کھال کی بنی ہوئی ڈھال تھی جس پر روٹی کے مانند گول سرخ چمڑا لگا ہوا تھا اور ان کے ساتھ ان کی کمان اور تیر بھی تھے۔ جب اس شاہی دربار کے قریب پہنچے اور سب سے پہلا بچھا ہوا قالین آ گیا تو ان لوگوں نے ان سے کہا کہ نیچے اتر جائیں لیکن یہ اپنے گھوڑے کو اس قالین پر لے گئے۔ جب وہ پوری طرح قالین پر چڑھ گیا تب یہ اس سے نیچے اترے اور پھر دو تکیوں کو لے کر انہیں پھاڑا اور گھوڑے کی لگام کی رسی اس میں سے گزار کر گھوڑے کو اس سے باندھ دیا۔ وہ لوگ انہیں ایسا کرنے سے نہ روک سکے۔ حضرت ربعیؓ دیکھتے ہی سمجھ گئے کہ یہ لوگ اپنا شاہی ٹھاٹھ باٹھ دکھا کر ہمیں مرعوب کرنا چاہتے ہیں، اس لیے انہوں نے یہ کام قصداً کیا تاکہ ان لوگوں کو پتہ چلے کہ انہوں نے اس سب کچھ سے کوئی اثر نہیں لیا۔ اور انہوں نے زرہ پہنی ہوئی تھی جو حوض کی طرح لمبی چوڑی تھی اور اونٹ کے گدے کو بیچ میں سے کاٹ کر بطور قبا کے اسے پہن رکھا تھا اور سن کی رسی سے اسے درمیان سے باندھ رکھا تھا۔ اور یہ عربوں میں سب سے زیادہ بالوں والے تھے۔ انہوں نے اونٹ کے چمڑے والی لگام سے اپنے بالوں کو باندھا ہوا تھا اور ان کے سر کے بالوں کی چار مینڈھیاں تھیں جو پہاڑی بکرے کے سینگوں کی طرح کھڑی ہوئی تھیں۔ ان لوگوں نے کہا آپ اپنے ہتھیار اتار کر یہاں رکھ دیں۔ انہوں نے کہا میں آپ لوگوں کے پاس خود نہیں آیا ہوں جو میں آپ کے کہنے پر اپنے ہتھیار اتار دوں، آپ لوگوں نے مجھے بلایا ہے۔ جیسے میں چاہتا ہوں ویسے مجھے آنے دیتے ہیں پھر تو ٹھیک ہے ورنہ میں واپس چلا جاتا ہوں۔ ان لوگوں نے رستم کو بتایا۔ رستم نے کہا اسے ایسے ہی آنے دو، وہ ایک ہی تو آدمی ہے۔ ان کے نیزے کے آگے نوکدار تیز پھل لگا ہوا تھا۔ وہ چھوٹے چھوٹے قدم رکھ کر اس نیزے پر ٹیک لگا کر چلنے لگے اور وہ یوں قالینوں اور بچھونوں میں سوراخ کرتے جا رہے تھے اور اس طرح انہوں نے ان کے تمام قالین پھاڑ دیے اور خراب کر دیے۔ جب یہ رستم کے قریب پہنچے تو پہرے داروں نے انہیں گھیرے میں لے لیا اور یہ بچھونے میں نیزہ گاڑ کر خود زمین پر بیٹھ گئے۔ ان لوگوں نے کہا آپ نے ایسا کیوں کیا؟ فرمایا ہم تمہاری زینت کے اس سامان پر بیٹھنا نہیں چاہتے۔ پھر رستم نے ان سے بات شروع کی اور کہا آپ لوگ ملکِ عرب سے کیوں آئے ہیں؟ فرمایا ",""],["ٱللَّٰه","a"],[" نے ہمیں بھیجا ہے اور وہی ہمیں یہاں اس لیے لے کر آیا ہے تاکہ ہم جسے وہ چاہے اسے بندوں کی عبادت سے نکال کر ",""],["ٱللَّٰه","a"],[" کی عبادت کی طرف اور دنیا کی تنگی سے نکال کر دنیا کی وسعت کی طرف اور ظلم والے ادیان سے نکال کر عدل والے دینِ اسلام کی طرف لے آئیں۔ اس کے بعد آگے ویسی حدیث ذکر کی ہے جیسے حضرت عمرؓ کے زمانۂ خلافت میں صحابہؓ کے دعوت دینے کے باب میں گزر چکی ہے۔ آگے حدیث میں یہ ہے کہ رستم نے اپنی قوم کے سرداروں سے کہا تمہارا ناس ہو، کپڑوں کو مت دیکھو، سمجھداری، گفتگو اور سیرت کو دیکھو۔ عرب کے لوگ کپڑے اور کھانے کا خاص اہتمام نہیں کرتے، ہاں خاندانی صفات کی بڑی حفاظت کرتے ہیں۔ اس حدیث میں یہ بھی ہے کہ پھر وہ لوگ حضرت ربعیؓ کے ہتھیاروں پر اعتراض کرنے لگے اور ان کے ہتھیاروں کو معمولی اور گھٹیا بتانے لگے۔ اس پر انہوں نے ان سے کہا تم اپنی جنگی مہارت مجھے دکھاؤ، میں اپنی تمہیں دکھاتا ہوں۔ یہ کہہ کر چیتھڑے میں سے اپنی تلوار باہر نکالی تو وہ آگ کے شعلے کی طرح چمک رہی تھی۔ ان لوگوں نے کہا بس کریں اور اسے نیام میں رکھ لیں۔ چنانچہ انہوں نے اسے نیام میں رکھ لیا۔ پھر حضرت ربعیؓ نے ان کی ڈھال پر تیر مارا تو وہ پھٹ گئی اور ان لوگوں نے حضرت ربعیؓ کی ڈھال پر تیر مارا تو وہ نہ پھٹی بلکہ صحیح سالم رہی۔ پھر فرمایا اے فارس والو! تم لوگوں نے کھانے پینے اور لباس کو بڑا کام بنا رکھا ہے، ہم انہیں چھوٹے کام سمجھتے ہیں۔ پھر حضرت ربعیؓ انہیں غور کرنے کے لیے (تین دن کی) مہلت دے کر واپس چلے گئے۔ اگلے دن رستم نے پیغام بھیجا کہ اسی آدمی کو پھر بھیج دیں۔ اس پر حضرت سعدؓ نے حضرت حذیفہ بن محصنؓ کو بھیجا۔ وہ بھی حضرت ربعیؓ کی طرح معمولی کپڑوں میں اور سیدھی سادی حالت میں چلے۔ جب پہلے قالین کے پاس پہنچے تو وہاں والوں نے کہا اب آپ سواری سے نیچے اتر جائیں۔ انہوں نے فرمایا میں تب اترتا اگر میں اپنی ضرورت کے لیے آتا۔ تم جا کر اپنے بادشاہ سے پوچھو کہ میں اس کی ضرورت کی وجہ سے آیا ہوں یا اپنی ضرورت کی وجہ سے۔ اگر وہ کہے میں اپنی ضرورت کی وجہ سے آیا ہوں تو بالکل غلط کہتا ہے، میں تمہیں چھوڑ کر واپس چلا جاؤں گا اور اگر وہ کہے میں اس کی ضرورت کی وجہ سے آیا ہوں تو پھر تم لوگوں کے پاس ویسے آؤں گا جیسے چاہوں گا۔ اس پر رستم نے کہا اسے اپنے حال پر چھوڑ دو، جیسے آتا ہے آنے دو۔ چنانچہ حضرت حذیفہؓ وہاں سے آگے چلے اور رستم کے پاس جا کر کھڑے ہو گئے۔ رستم اپنے تخت پر بیٹھا ہوا تھا۔ اس نے کہا نیچے اتر جائیں۔ حضرت حذیفہؓ نے کہا میں نہیں اتروں گا۔ جب انہوں نے اترنے سے انکار کر دیا تو رستم نے ان سے پوچھا کہ کیا بات ہے آج آپ آئے ہیں، ہمارے کل والے ساتھی نہیں آئے؟ حضرت حذیفہؓ نے کہا ہمارے امیر سختی نرمی ہر حال میں ہمارے درمیان برابری کرنا چاہتے ہیں۔ کل وہ آئے تھے، آج میری باری ہے۔ رستم نے کہا آپ لوگ کیوں آئے ہیں؟ فرمایا ",""],["ٱللَّٰه","a"],[" نے ہمیں اپنا دین عطا فرما کر ہم پر بڑا احسان فرمایا، ہمیں اپنی نشانیاں دکھائیں یہاں تک کہ ہم نے اسے پہچان لیا، حالانکہ ہم اس سے پہلے اسے بالکل نہیں جانتے تھے۔ پھر ",""],["ٱللَّٰه","a"],[" نے ہمیں حکم دیا کہ ہم تمام لوگوں کو تین باتوں میں سے ایک بات کی دعوت دیں۔ ان باتوں میں سے جسے بھی وہ مان لیں گے اسے ہم قبول کر لیں گے۔ پہلی بات یہ ہے کہ اسلام لے آؤ۔ اگر اسلام لے آؤ گے تو ہم تمہیں چھوڑ کر واپس چلے جائیں گے۔ دوسری بات یہ ہے کہ اگر اسلام نہیں لاتے تو پھر جزیہ ادا کرو۔ اگر جزیہ ادا کرو گے اور تمہیں ضرورت پڑی تو ہم تمہاری دشمن سے حفاظت کریں گے۔ تیسری بات یہ ہے کہ یہ دونوں باتیں منظور نہ ہوں تو پھر لڑائی اور مقابلہ۔ رستم نے کہا کیا چند دن تک کے لیے صلح ہو سکتی ہے؟ فرمایا ہاں، تین دن تک کے لیے ہو سکتی ہے لیکن وہ تین دن کل گزشتہ سے شمار ہوں گے۔ جب رستم نے حضرت حذیفہؓ سے بھی وہی جواب پایا جو حضرت ربعیؓ سے سنا تھا تو اس نے حضرت حذیفہؓ کو واپس کر دیا اور اپنے ساتھیوں کی طرف متوجہ ہو کر کہنے لگا تمہیں میری رائے سمجھ میں کیوں نہیں آ رہی؟ کل ہمارے پاس پہلا آدمی آیا، وہ ہم پر غالب آ گیا اور ہمارے قالین پر نہ بیٹھا (بلکہ ہمارے انتظامات چھوڑ کر) ہماری زمین پر بیٹھ گیا اور اس نے اپنا گھوڑا ہماری زینت کے سامان کے اوپر کھڑا کیا اور ہم نے زینت کے لیے جو تکیے رکھے تھے ان کے ساتھ اپنا گھوڑا باندھ دیا۔ اسے اچھی فال لینے کا موقع مل گیا کیونکہ وہ ہماری زمین کو بھی اپنے ساتھیوں کے پاس لے گیا اور زمین میں جو کچھ تھا اسے بھی لے گیا۔ ان تمام باتوں کے باوجود وہ عقلمند بھی بہت تھا۔ آج یہ دوسرا آدمی ہمارے پاس آیا تو یہ آ کر ہمارے سر پر کھڑا ہو گیا، یہ بھی اچھی فال لے کر گیا ہے، یہ تو ہمیں نکال کر ہماری زمین پر قبضہ کر لے گا۔ (رستم کے ساتھیوں نے رستم کی باتوں کا سخت جواب دیا) اور ان میں بات چیت اتنی بڑھی کہ رستم کو بھی غصہ آ گیا اور اس کے ساتھیوں کو بھی۔ اگلے دن رستم نے پیغام بھیجا کہ ہمارے پاس ایک آدمی بھیجو۔ چنانچہ مسلمانوں نے حضرت مغیرہ بن شعبہؓ کو بھیجا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer (Vol.3 Pg.33)."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں جب حضرت مغیرہؓ پل پر پہنچے اور پل پار کر کے فارس والوں کے پاس جانا چاہا تو انہیں پہرے داروں نے روکا اور رستم سے ان کے بارے میں اجازت طلب کی۔ اور انہوں نے صحابہ کرامؓ کو مرعوب کرنے کے لیے جو شاہی انتظامات کر رکھے تھے وہ سارے اسی طرح سے تھے، انہوں نے کوئی تبدیلی نہیں کی تھی۔ ان لوگوں نے تاج اور قیمتی کپڑے جو کہ سونے کے تاروں سے بنے ہوئے تھے پہنے ہوئے تھے اور تیر پھینکنے سے تیر جتنی دور جاتا ہے اتنی دور تک قالین بچھائے ہوئے تھے۔ ان پر چل کر ہی آدمی ان کے بادشاہ تک پہنچ سکتا تھا۔ بہرحال رستم کے اجازت دینے پر حضرت مغیرہؓ وہاں سے آگے چلے۔ ان کے سر کے بالوں کی چار مینڈھیاں بنی ہوئی تھیں۔ وہ چلتے چلتے جا کر رستم کے ساتھ اس کے تخت اور گدے پر بیٹھ گئے۔ اور اس پر وہ سب لوگ حضرت مغیرہؓ پر جھپٹے اور بڑبڑائے اور جھنجھوڑ کر انہیں تخت سے نیچے اتار دیا۔ حضرت مغیرہؓ نے فرمایا ہمیں تو یہ خبر پہنچی تھی کہ آپ لوگ بڑے سمجھدار ہیں لیکن میں نے آپ لوگوں سے زیادہ بے وقوف قوم کوئی نہیں دیکھی۔ ہم تمام عرب لوگ آپس میں برابر ہیں، ہم میں سے کوئی کسی کو اپنا غلام نہیں بناتا، ہاں کسی سے جنگ ہو تو پھر اور بات ہے۔ میرا خیال تھا کہ آپ لوگ بھی آپس میں ہماری طرح رہتے ہوں گے۔ اور آپ لوگوں نے جو کچھ کیا اس سے اچھا تو یہ تھا کہ مجھے پہلے ہی بتا دیتے کہ آپ لوگ آپس میں برابر کے نہیں بلکہ ایک دوسرے کے رب ہیں۔ اگر رستم کے ساتھ بیٹھنا آپ لوگوں کے خیال میں ٹھیک نہیں ہے تو آئندہ ہم ایسا نہیں کریں گے۔ آپ لوگوں کے پاس میں خود نہیں آیا ہوں، آپ لوگوں نے بلایا تو میں آیا ہوں۔ آج مجھے پتہ چلا کہ تمہارا نظام ڈھیلا پڑ چکا ہے اور تم لوگ مغلوب ہونے والے ہو اور اس طور طریقہ پر اور اس سمجھ پر ملک باقی نہیں رہ سکتا۔ یہ باتیں سن کر عام لوگ کہنے لگے ",""],["ٱللَّٰه","a"],[" کی قسم! یہ عربی بالکل ٹھیک کہہ رہا ہے۔ ان کے چودھری کہنے لگے ",""],["ٱللَّٰه","a"],[" کی قسم! اس نے تو ایسی بات کہی ہے کہ ہمارے غلام ہمیں ہمیشہ اس کی طرف کھینچتے رہیں گے۔ ",""],["ٱللَّٰه","a"],[" ہمارے پہلوں کو غارت کرے، کس قدر احمق تھے کہ ان عربوں کی بات کو معمولی سمجھتے رہے (آج یہ اتنے زوروں پر آ گئے ہیں، انہیں چاہیے تھا کہ ان عربوں کو شروع میں ہی کچل دیتے)۔ اس کے بعد راوی نے باقی حدیث ذکر کی ہے جس میں رستم کے سوالات اور حضرت مغیرہؓ کے جوابات کا ذکر ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Jareer (Vol.3 Pg.36)."]]}]},"295":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں میں غزوۂ موتہ میں شریک ہوا۔ جب مشرکین ہمارے قریب پہنچے تو ہمیں بہت زیادہ سامان، ہتھیار، گھوڑے، ریشمی کپڑے اور سونا نظر آیا اور یہ سب کچھ اتنا زیادہ تھا کہ اس کا مقابلہ کوئی نہیں کر سکتا تھا۔ اسے دیکھ کر میری تو آنکھیں چندھیا گئیں۔ مجھے یوں متاثر ہوتا ہوا دیکھ کر حضرت ثابت بن اقرمؓ نے فرمایا اے ابوہریرہ! ایسے نظر آ رہا ہے کہ تم بہت زیادہ لشکر دیکھ رہے ہو؟ میں نے کہا جی ہاں! انہوں نے فرمایا تم ہمارے ساتھ غزوۂ بدر میں نہیں تھے، تعداد یا سامان کی کثرت کی وجہ سے ہماری مدد نہیں ہوئی تھی۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi from Waaqidi, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.244). It is also mentioned in Isaabah (Vol.1 Pg.190)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں حضرت ابوبکرؓ نے حضرت عمرو بن عاصؓ کو یہ خط لکھا: \"سلام علیک! اما بعد! آپ کا خط میرے پاس آیا جس میں آپ نے اس بات کا ذکر کیا ہے کہ رومیوں نے بہت زیادہ لشکر جمع کر لیے ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے نبیؐ کے ساتھ ہماری مدد سامان یا لشکر کی کثرت کی وجہ سے نہیں کی تھی۔ ہم حضورؐ کے ساتھ غزوات میں جایا کرتے تھے اور ہمارے پاس صرف دو گھوڑے ہوتے تھے اور اونٹ بھی ضرورت سے کم ہوتے تھے، اس لیے ان پر باری باری سوار ہوتے تھے۔ اور جنگِ احد کے دن ہم حضورؐ کے ساتھ تھے اور ہمارے پاس صرف ایک گھوڑا تھا جس پر حضورؐ سوار تھے۔ اس بے سروسامانی میں ",""],["ٱللَّٰه","a"],[" تعالیٰ مخالفوں کے خلاف ہماری مدد کرتے تھے۔ اے عمرو! آپ کو معلوم ہونا چاہیے کہ ",""],["ٱللَّٰه","a"],[" کی سب سے زیادہ ماننے والا ہے جو گناہوں اور معاصی سے سب سے زیادہ نفرت کرنے والا ہے، لہٰذا آپ ",""],["ٱللَّٰه","a"],[" کی اطاعت کرو اور اپنے ساتھیوں کو اس کی اطاعت کا حکم کرو۔\"",""],[" (2)","s"]]]],"f":[["(2)","Tayaalisi, as quoted in Kanzul Ummaal (Vol.3 Pg.135). Tabraani has reported a similar narration in his Awsat, but Haythami (Vol.6 Pg.117) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبادہ اور حضرت خالدؓ","b"],[" فرماتے ہیں ایک آدمی نے حضرت خالدؓ سے کہا رومی کتنے زیادہ ہیں اور مسلمان کتنے کم ہیں۔ حضرت خالدؓ نے فرمایا نہیں، رومی کتنے کم ہیں اور مسلمان کتنے زیادہ ہیں۔ لشکر کا کم زیادہ ہونا آدمیوں کی تعداد سے نہیں ہوتا بلکہ جس لشکر کو ",""],["ٱللَّٰه","a"],[" کی مدد حاصل ہو وہ زیادہ ہے اور جو ",""],["ٱللَّٰه","a"],[" کی مدد سے محروم ہو وہ کم ہے (میں عراق سے شام تک کا سفر بڑی تیزی سے کر کے آیا ہوں، اس لیے) زیادہ چلنے کی وجہ سے میرے گھوڑے اشقر کے کھر گھس گئے ہیں اور اس کے کھروں میں درد ہو رہا ہے۔ کاش کہ میرا گھوڑا ٹھیک ہوتا اور ان رومیوں کی تعداد دگنی ہوتی تو پھر مزہ آتا۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Jareer (Vol.2 Pg.594)."]]}]},"296":{"lead":[],"stories":[{"b":[["n",[["حضرت زہریؒ","b"],[" کہتے ہیں جب ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت ابوبکرؓ کو خلیفہ بنا دیا اور عرب کے بہت سے لوگ مرتد ہو کر اسلام سے خارج ہو گئے تو حضرت ابوبکرؓ مقابلہ کے لیے مدینہ سے چلے۔ جب بقیع کی طرف ایک پانی پر پہنچے تو انہیں مدینہ کے بارے میں خطرہ محسوس ہوا، اس لیے حضرت ابوبکرؓ مدینہ واپس آ گئے (اور دوسروں کو بھیجنے کا ارادہ کیا) اور حضرت خالد بن ولید بن مغیرہ سیف ",""],["ٱللَّٰه","a"],["ؓ کو امیر مقرر فرما کر لوگوں کو ان کے ساتھ جانے کی دعوت دی اور حضرت خالدؓ کو حکم دیا کہ وہ قبیلہ مضر کے علاقہ میں جائیں اور وہاں جتنے لوگ مرتد ہو چکے ہیں ان سے جنگ کریں، پھر وہاں سے یمامہ جا کر مسیلمہ کذاب سے جنگ کریں۔ چنانچہ حضرت خالد بن ولیدؓ وہاں سے لشکر لے کر چلے اور پہلے طلیحہ کذاب اسدی سے جنگ کی۔ ",""],["ٱللَّٰه","a"],[" نے طلیحہ کو شکست دی۔ عیینہ بن حصن بن حذیفہ فزاری بھی طلیحہ کذاب کے پیچھے لگ گیا تھا۔ جب طلیحہ نے دیکھا کہ اس کے ساتھیوں کو بہت زیادہ شکست ہو رہی ہے تو اس نے کہا تمہارا ناس ہو، کہ ہمیں شکست کیوں ہو جاتی ہے؟ اس کی وجہ یہ ہے کہ ہم میں سے ہر آدمی یہ چاہتا ہے کہ اس کا ساتھی اس سے پہلے مر جائے اور ہمارا مقابلہ ایسے لوگوں سے ہے جن میں سے ہر آدمی اپنے ساتھی سے پہلے مرنا چاہتا ہے۔ طلیحہ لڑنے میں سخت حملہ آور تھا۔ چنانچہ اس نے حضرت عکاشہ بن محصن اور حضرت ابن اقرمؓ کو شہید کیا۔ جب طلیحہ نے حق کو غالب آتے دیکھا تو پہلے تو پیدل بھاگا، پھر بعد میں اسلام لے آیا اور عمرہ کا احرام باندھا۔ اس کے بعد باقی حدیث ذکر کی۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi (Vol.8 Pg.175)."]]},{"b":[["n",[["حضرت عمرو بن عاصؓ","b"],[" فرماتے ہیں مسلمانوں کا ایک لشکر روانہ ہوا، میں ان کا امیر تھا۔ چلتے چلتے ہم اسکندریہ پہنچے تو وہاں کے بادشاہ نے پیغام بھیجا کہ اپنا ایک آدمی میرے پاس بھیجو تاکہ میں اس سے بات کروں اور وہ مجھ سے بات کرے۔ میں نے ساتھیوں سے کہا میں خود ہی اس کے پاس جاؤں گا۔ چنانچہ میں ترجمان لے کر گیا۔ اس کے پاس آدمی بھی ترجمان تھا۔ ہمارے لیے دو منبر رکھے گئے۔ اس نے پوچھا آپ لوگ کون ہیں؟ میں نے کہا ہم عرب ہیں۔ ہمارے ہاں کانٹے دار درخت اور کیکر ہوتے ہیں (کھیتیاں اور باغات نہیں ہوتے) البتہ ہمارے ہاں بیت ",""],["ٱللَّٰه","a"],[" ہے۔ ہمارا علاقہ سب سے زیادہ تنگ تھا اور ہمارے معاشی حالات سب سے زیادہ سخت تھے۔ ہم مردار کھا لیتے تھے اور ایک دوسرے کا مال لوٹ لیتے تھے، غرضیکہ ہماری زندگی سب سے زیادہ بری تھی۔ پھر ایک آدمی ہمارے اندر ظاہر ہوا جو ہمارا سب سے بڑا سردار نہیں تھا اور ہم میں سب سے زیادہ مالدار نہیں تھا۔ اس نے کہا میں ",""],["ٱللَّٰه","a"],[" کا رسول ہوں۔ وہ ہمیں ان کاموں کا حکم کرتے ہیں جنہیں ہم جانتے نہیں تھے اور جن کاموں پر ہم اور ہمارے آباء و اجداد پڑے ہوئے تھے ان سے ہمیں روکتے تھے۔ ہم نے ان کی مخالفت کی اور انہیں جھٹلایا اور ان کی بات کو رد کر دیا یہاں تک کہ ان کے پاس دوسری قوم کے لوگ آئے اور انہوں نے کہا ہم آپ کی تصدیق کرتے ہیں، آپ پر ایمان لاتے ہیں، آپ کا اتباع کرتے ہیں اور جو آپ سے جنگ کرے گا ہم اس سے جنگ کریں گے۔ وہ ہمیں چھوڑ کر ان کے پاس چلے گئے۔ ہم نے وہاں جا کر ان سے کئی مرتبہ جنگ کی۔ انہوں نے ہمارے بہت سے آدمی قتل کر دیے اور ہم پر غالب آ گئے۔ پھر وہ آس پاس کے عربوں کی طرف متوجہ ہوئے اور جنگ کر کے ان پر بھی غالب آ گئے۔ اب جو لوگ میرے پیچھے ہیں اگر ان کو آپ لوگوں کی عیش و عشرت کا پتہ چل جائے تو وہ سب آ کر اس عیش و عشرت میں آپ کے شریک ہو جائیں۔ یہ بات سن کر وہ بادشاہ ہنسا اور اس نے کہا آپ کے رسول نے سچ کہا ہے اور ہمارے پاس ہمارے رسول بھی وہی چیزیں لاتے رہے ہیں جو آپ کے رسول آپ کے پاس لائے ہیں۔ ہم ان رسولوں کی باتوں پر عمل کرتے رہے، پھر ہم میں کچھ بادشاہ ظاہر ہوئے جو ان نبیوں کی باتوں کو چھوڑ کر ہمیں اپنی خواہشات پر چلاتے رہے۔ اگر آپ لوگ اپنے نبیؐ کی بات کو مضبوطی سے پکڑے رہیں گے تو جو بھی آپ لوگوں سے لڑے گا آپ لوگ اس پر ضرور غالب آ جائیں گے اور جو بھی آپ لوگوں کی طرف ہاتھ بڑھائے گا آپ لوگ اس پر ضرور حاوی ہو جائیں گے۔ پھر جب آپ لوگ اس طرح کریں گے جس طرح ہم نے کیا اور نبیوں کی بات چھوڑ کر ہمارے بادشاہوں کی طرح خواہشات پر عمل کریں گے تو پھر آپ اور ہم برابر ہو جائیں گے یعنی آپ لوگ بھی ہماری طرح ",""],["ٱللَّٰه","a"],[" کی مدد سے محروم ہو جائیں گے، پھر نہ آپ کی تعداد ہم سے زیادہ ہوگی اور نہ طاقت (لہٰذا ہم آپ پر غالب آئیں گے)۔ حضرت عمرو بن عاصؓ فرماتے ہیں میں نے کبھی کسی ایسے آدمی سے بات نہیں کی جو اس سے زیادہ نصیحت کرنے والا ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani; Haythami (Vol.6 Pg.218) has commented on the chain of narrators. Abu Ya'la has reported a similar narration (Haythami Vol.8 Pg.238)."]]},{"b":[["n",[["حضرت ابواسحاقؒ","b"],[" کہتے ہیں حضورؐ کے صحابہؓ کے سامنے دشمن مقابلہ کے وقت اتنی دیر بھی نہیں ٹھہر پاتا تھا جتنا وقفہ اونٹنی کے دو مرتبہ دودھ نکالنے کے درمیان ہوتا ہے۔ (اونٹنی کے دودھ نکالنے کی صورت یہ ہوتی ہے کہ اس کا دودھ اوپر چڑھا ہوا ہوتا ہے، تھنوں میں کم ہوتا ہے۔ پہلے اونٹنی کے بچے کو دودھ پینے کے لیے لایا جاتا ہے، وہ دودھ پیتا ہے تو دودھ نیچے اتر آتا ہے۔ بچے کو ہٹا کر آدمی دودھ نکالنے لگتا ہے تو اونٹنی اپنا دودھ اوپر چڑھا لیتی ہے، اس لیے دوبارہ بچہ لایا جاتا ہے، وہ پینے لگتا ہے تو دودھ پھر نیچے اتر آتا ہے تو بچے کو ہٹا کر دوبارہ نکالا جاتا ہے۔ اس طرح ایک وقت میں اونٹنی کا سارا دودھ دو دفعہ نکالنے سے حاصل ہوتا ہے تو ان دو دفعہ دودھ نکالنے کا درمیانی وقفہ چند منٹ کا ہوتا ہے۔ دوسری صورت یہ ہو سکتی ہے کہ جب اونٹنی کا دودھ نکالتے ہیں اس وقت وہ کھڑی ہوتی ہے تو نکالنے والا ایک ٹانگ پر کھڑا ہوتا ہے اور دوسری ٹانگ اٹھا کر اپنا پاؤں پہلی ٹانگ کے گھٹنے پر رکھ لیتا ہے اور اس دوسری ٹانگ کے گھٹنے اور ران پر برتن رکھ کر اس میں دودھ نکالتا ہے۔ اس طرح نکالنے والا تھک جاتا ہے اور ایک ٹانگ پر کھڑے ہونے کی وجہ سے گرنے والا ہو جاتا ہے تو وہ برتن نیچے رکھ کر اور دونوں ٹانگیں سیدھی زمین پر ٹکا کر کچھ دیر آرام کرتا ہے، پھر اسی طرح ایک ٹانگ پر کھڑے ہو کر دوبارہ دودھ نکالتا ہے تو یہ آرام کا درمیانی وقفہ یہاں مراد ہے (یہ وقفہ بھی چند منٹ کا ہوتا ہے)۔) روم کا بادشاہ ہرقل انطاکیہ میں قیام پذیر تھا۔ جب رومی فوج مسلمانوں سے شکست کھا کر وہاں پہنچی تو اس نے فوج سے کہا تمہارا ناس ہو! تم مجھے ان لوگوں کے بارے میں بتاؤ جو تم سے جنگ کر رہے ہیں، کیا یہ تمہارے جیسے انسان نہیں ہیں؟ ان سب جرنیلوں نے کہا ہیں۔ ہرقل نے کہا تمہاری تعداد زیادہ ہے یا ان کی؟ انہوں نے کہا نہیں، ہر معرکہ میں ہماری تعداد ان سے کئی گنا زیادہ تھی۔ ہرقل نے کہا پھر کیا بات ہے تمہیں شکست کیوں ہو جاتی ہے؟ اس پر ایک بوڑھے جرنیل نے کہا اس کی وجہ یہ ہے کہ وہ لوگ رات کو عبادت کرتے ہیں اور دن کو روزہ رکھتے ہیں اور معاہدہ کو پورا کرتے ہیں اور نیکی کا حکم کرتے ہیں، برائی سے روکتے ہیں اور آپس میں انصاف کرتے ہیں۔ اور اس کے برعکس ہم لوگ شراب پیتے ہیں، زنا کرتے ہیں، ہر حرام کا ارتکاب کرتے ہیں، معاہدہ توڑ دیتے ہیں، ایک دوسرے کا مال چھین لیتے ہیں اور ظلم کرتے ہیں اور ان کاموں کا حکم کرتے ہیں جن سے ",""],["ٱللَّٰه","a"],[" ناراض ہوتا ہے اور جن کاموں سے ",""],["ٱللَّٰه","a"],[" راضی ہوتا ہے ان سے ہم روکتے ہیں اور زمین میں فساد پھیلاتے ہیں۔ ہرقل نے کہا تم نے مجھ سے سچی بات کہی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad bin Marwaan Maaliki in his Mujaalasa, as quoted in Al Bidaayah wan Nihaayah (Vol.7 Pg.15). Ibn Asaakir (Vol.1 Pg.143) has reported a similar narration."]]},{"b":[["n",[["یحییٰ بن یحییٰ غسانیؒ","b"],[" اپنی قوم کے دو آدمیوں سے نقل کرتے ہیں کہ جب مسلمانوں نے اردن کے کنارے پر پڑاؤ ڈالا تو ہم نے آپس میں کہا دمشق کا عنقریب محاصرہ ہونے والا ہے، اس لیے ہم دمشق گئے تاکہ محاصرہ شروع ہونے سے پہلے ہی وہاں سے خرید و فروخت کر لیں۔ ہم ابھی دمشق میں تھے کہ دمشق کے کمانڈر نے ہمارے پاس بلانے کے لیے قاصد بھیج دیا۔ ہم اس کے پاس گئے۔ اس نے کہا کیا تم دونوں عرب ہو؟ ہم نے کہا جی ہاں! اس نے کہا کیا تمہارا مذہب نصرانیت ہے؟ ہم نے کہا جی ہاں۔ اس نے کہا ہم دونوں میں سے ایک جا کر ان مسلمانوں کے حالات معلوم کر کے آئے، دوسرا اس کے سامان کے پاس ٹھہر جائے۔ چنانچہ ہم دونوں میں سے ایک گیا اور مسلمانوں میں کچھ دیر ٹھہر کر واپس آیا اور اس نے کہا میں ایسے لوگوں کے پاس سے آ رہا ہوں جو دبلے پتلے ہیں، عمدہ اور اصیل گھوڑوں پر سوار ہوتے ہیں، رات کے عبادت گزار اور دن کے شہسوار ہیں، تیر میں پر لگاتے ہیں، اسے تراشتے ہیں، نیزے کو بالکل سیدھا کرتے ہیں۔ وہ اتنی اونچی آواز سے قرآن پڑھتے ہیں اور ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے ہیں کہ اگر آپ ان میں بیٹھ کر اپنے ہم نشین سے کوئی بات کریں تو شور کی وجہ سے آپ کی بات کو سمجھ نہیں سکے گا۔ اس پر دمشق کے کمانڈر نے اپنے ساتھیوں کی طرف متوجہ ہو کر کہا مسلمانوں کے ان حالات کے معلوم ہو جانے کے بعد اب تم ان کا مقابلہ نہیں کر سکتے۔",""]]],["p",[["[نوٹ: اس نسخے کے اسکین میں اصل کتاب کے صفحات 716 اور 717 موجود نہیں ہیں، اس لیے ان دو صفحات کا متن یہاں شامل نہیں کیا جا سکا۔ مکمل نسخہ ملنے پر یہ حصہ شامل کیا جائے۔]",""],[" (4)","s"]]]],"f":[["(4)","Al Bidaayah wan Nihaayah (Vol.7 Pg.15). Ibn Asaakir (Vol.1 Pg.143) has reported a similar narration."]]},{"b":[["n",[["… سے جنگ کریں گے۔ پھر اس نے پوچھا وہ اپنے امیروں کی اطاعت کرنے میں کیسے ہیں؟ میں نے کہا وہ اپنے امیر کی سب سے زیادہ اطاعت کرنے والے لوگ ہیں۔ پھر اس نے پوچھا وہ کن چیزوں کو حلال سمجھتے ہیں اور کن چیزوں کو حرام؟ میں نے اسے مسلمانوں کے حلال و حرام کی تفصیل بتائی۔ اس نے پوچھا کیا وہ حلال کو حرام اور حرام کو حلال کر لیتے ہیں؟ میں نے کہا نہیں۔ اس نے کہا جب تک یہ لوگ حرام کو حلال اور حلال کو حرام نہیں کریں گے اس وقت تک یہ ہلاک نہیں ہوں گے۔ مجھے ان کے لباس کے بارے میں بتاؤ؟ میں نے ان کے لباس کی تفصیل بتائی۔ پھر اس نے کہا ان کی سواریوں کے بارے میں بتاؤ؟ میں نے کہا ان کی سواریاں عربی گھوڑے ہیں۔ پھر میں نے عربی گھوڑوں کی صفات ذکر کیں۔ اس نے کہا یہ تو بہت اچھے قلعے ہیں۔ پھر میں نے کہا ان کی سواریاں اونٹ بھی ہیں اور اونٹ کے بیٹھنے اور بوجھ اٹھا کر کھڑے ہونے کا سارا انداز بتایا۔ اس نے کہا یہ تمام باتیں لمبی گردن والے جانور میں ہوا کرتی ہیں (غالباً شاہِ چین نے اونٹ دیکھا نہ ہوگا)۔ پھر اس نے یزدجرد کو جواب میں یہ لکھا کہ میرے پاس اتنا بڑا لشکر ہے کہ اگر میں اسے آپ کی مدد کے لیے بھیجوں تو اس کا پہلا حصہ ایران کے شہر مرو میں ہوگا اور آخری چین میں، لیکن میں اسے نہیں بھیجوں گا۔ اور اسے نہ بھیجنے کی وجہ یہ نہیں ہے کہ آپ کا جو مجھ پر حق ہے میں اسے نہیں جانتا بلکہ اس کی وجہ یہ ہے کہ آپ کا جن لوگوں سے مقابلہ ہے آپ کے قاصد نے ان کے تمام حالات مجھے تفصیل سے بتائے ہیں۔ یہ ایسے زبردست لوگ ہیں کہ اگر یہ پہاڑوں سے ٹکرا جائیں تو پہاڑ ریزہ ریزہ ہو جائیں۔ اگر یہ اپنی ان صفات پر باقی رہے اور یونہی بڑھتے رہے تو ایک دن مجھے بھی میری سلطنت سے ہٹا دیں گے، اس لیے آپ ان سے صلح کر لیں اور صلح صفائی کے ساتھ ان کے ساتھ رہنے پر راضی ہو جائیں اور جب تک وہ آپ کو نہ چھیڑیں آپ انہیں کچھ نہ کہیں۔",""]]],["p",[["ہم اس کتاب میں جو کچھ لکھنا چاہتے ہیں یہ اس کا آخری مضمون ہے۔",""]]],["q",[["فَالْحَمْدُ لِلّٰهِ الَّذِيْ هَدَانَا لِهٰذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللّٰهُ","a"]]],["p",[["\"تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے ہمیں اس خیر کی ہدایت نصیب فرمائی۔ اگر ",""],["ٱللَّٰه","a"],[" ہمیں ہدایت نہ دیتے تو ہم از خود ہدایت نہ پا سکتے۔\"",""]]],["q",[["اَللّٰهُمَّ لَوْلَا أَنْتَ مَا اهْتَدَيْنَا ۝ وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا","a"]]],["q",[["فَأَنْزِلَنْ سَكِيْنَةً عَلَيْنَا ۝ إِذَا أَرَادُوْا فِتْنَةً أَبَيْنَا","a"]]],["p",[["اے ",""],["ٱللَّٰه","a"],["! اگر تیری مہربانی شاملِ حال نہ ہوتی تو ہمیں ہدایت نہ ملتی اور نہ ہم صدقہ دیتے اور نہ نماز پڑھتے۔ تو ہم پر اطمینان اور سکینہ نازل فرما۔ جب مشرک لوگ ہم سے فتنہ والا کام کرانا چاہتے ہیں تو ہم انکار کر دیتے ہیں۔",""]]],["p",[["آج بروز بدھ محرم الحرام کے مہینے میں ہجرتِ نبوی (علیٰ صاحبہا الف الف صلاۃ وتحیۃ) کے تیرہ سو اناسی والے سال میں عبدِ ضعیف محمد یوسف سلمہ ",""],["ٱللَّٰه","a"],[" تعالیٰ عن التلہف والتاسف کے ہاتھوں کتاب \"حیاۃ الصحابہؓ\" مکمل ہوئی۔",""]]],["p",[["ٱللَّٰه","a"],[" تعالیٰ کی توفیق سے کتاب کی تیسری جلد کی طباعت منگل 12 ربیع الثانی 1385ھ مطابق 10 اگست 1965ء کو پوری ہوئی۔",""]]],["p",[["ٱللَّٰه","a"],[" تعالیٰ کے فضل و کرم سے آج بروز بدھ 27 شوال 1415ھ مطابق 29 مارچ 1995ء کو ترجمہ مکمل ہوا۔",""]]],["p",[["محمد احسان الحق","b"],["، مدرسہ عربیہ رائے ونڈ، لاہور۔ پاکستان",""],[" (5)","s"]]]],"f":[["(5)","Ibn Jareer (Vol.3 Pg.249)."]]}]}}});
